window.STUDY_FOCUS = [{"id": "functions", "title": "Arrow functions", "subtitle": "Know what a function returns", "icon": "↗", "color": "purple", "module": "arrow-functions", "exercise": "e01", "lab": "map", "question": "q01", "diagram": "arrow-functions", "cheat": 0, "idea": "An arrow function is a value you can pass around. When it runs, it receives arguments and may return a result.", "takeaway": "An expression body returns its value. A block needs return when you want a result.", "example": "const double = n => n * 2;\nconst alsoDouble = n => { return n * 2; };\nconst missingReturn = n => { n * 2; };\n\ndouble(3); // 6\nmissingReturn(3); // undefined", "steps": [[[0, 4], "An expression body returns the expression. With n = 3, n * 2 becomes 6."], [[1], "Braces create a function block. The explicit return sends the result back to the caller."], [[2, 5], "A block can calculate a value and discard it. Without return, this function returns undefined."]], "prompt": "Write a function that adds 1 to a number. Show an expression body and a block body. Predict the result when the input is 4.", "hint": "Keep the calculation the same. Only the block version needs the return keyword.", "solution": "const addOne = n => n + 1;\nconst addOneBlock = n => { return n + 1; };\n// Both return 5 when called with 4.", "explain": "Both versions receive one number and return a new number. The braces change how you write the return, not the intended calculation.", "quiz": "What does this call return?", "quizcode": "const double = n => { n * 2; };\ndouble(4);", "options": ["8", "undefined", "A syntax error"], "correct": 1, "responses": ["The calculation produces 8, but the block never returns it. Look for a return statement.", "The block has no return statement, so the call returns undefined. Write n => n * 2 or n => { return n * 2; }.", "This is valid JavaScript syntax. The issue is the missing return value, which changes the behavior."]}, {"id": "lists", "title": "Map and lists", "subtitle": "Turn data into visible elements", "icon": "≡", "color": "blue", "module": "map-lists", "exercise": "e02", "lab": "map", "question": "q03", "diagram": "map-lists", "cheat": 1, "idea": "map calls a function once for each array item. It puts each returned value into a new array. Those values can be elements to display.", "takeaway": "Return an element for each item, and put a stable key on each returned sibling.", "example": "// Component fragment; Text and View are imported.\nconst names = ['Tea', 'Soup'];\nconst rows = names.map(name => (\n  <Text key={name}>{name}<\/Text>\n));\nreturn <View>{rows}<\/View>;", "steps": [[[1, 2], "The callback receives one name at a time: first Tea, then Soup."], [[3], "Each call returns a Text element. These fixed, unique names can be keys here; editable data should have stable IDs."], [[4, 5], "map returns the array of elements. JSX braces insert that array into the View."]], "prompt": "Given [2, 5, 8], use map to add 1 to every number. Write both arrow-body styles. Predict the result and whether the original changes.", "hint": "The callback receives one number. Its return value becomes one entry in the result.", "solution": "const numbers = [2, 5, 8];\nconst result = numbers.map(n => n + 1);\nconst sameResult = numbers.map(n => { return n + 1; });\n// Results: [3, 6, 9]. numbers remains [2, 5, 8].", "explain": "This transformation creates a new array. Each callback returns a new number and does not mutate the input.", "quiz": "Which result does this map produce?", "quizcode": "[2, 5, 8].map(n => { n + 1; });", "options": ["[3, 6, 9]", "[2, 5, 8]", "[undefined, undefined, undefined]"], "correct": 2, "responses": ["That would be the result if the callback returned n + 1. This block does not return a value.", "The original array stays [2, 5, 8], but map returns a separate result array.", "Each of the three callback calls returns undefined because its block lacks return."]}, {"id": "state", "title": "Array state", "subtitle": "Build the next value safely", "icon": "+", "color": "teal", "module": "immutable-updates", "exercise": "e04", "lab": "state", "question": "q09", "diagram": "immutable-updates", "cheat": 4, "idea": "State describes a render. To add an item, create a new array and ask React to use it in the next render.", "takeaway": "A setter accepts a new value or a pure updater function. Square brackets create the new array.", "example": "// Inside an add-event handler; menu and setMenu already exist.\nconst newItem = { id: 'b', name: 'Soup' };\nsetMenu(previous => [...previous, newItem]);\n\n// Also valid using this render's menu:\n// setMenu([...menu, newItem]);", "steps": [[[1], "Create the item outside the updater. In an app, assign a new stable ID when each item is created."], [[2], "React supplies previous queued state. ...previous copies its entries into a new array, then newItem is appended."], [[4, 5], "A direct replacement is also valid. Prefer an updater when the result depends on previous state, especially for multiple queued updates."]], "prompt": "Assume menu is array state and item is a new menu item. Write an add handler that appends item without changing the existing array.", "hint": "Use a functional updater. Its parameter is the previous array, and it must return the next array.", "solution": "const addItem = item => {\n  setMenu(previous => [...previous, item]);\n};\n// Component-body fragment in JavaScript.\n// In TypeScript, annotate item with MenuItem.", "explain": "The updater receives previous queued state and returns a new array. Do not use push on the state array. Object braces would produce a different shape.", "quiz": "Is this update valid?", "quizcode": "setMenu(previous => [...previous, item]);", "options": ["Yes: the updater returns the next array.", "No: a setter cannot receive a function.", "No: spread changes the original array."], "correct": 0, "responses": ["React calls the updater with previous queued state. The array literal returns a new array with the old entries and new item.", "State setters do accept updater functions. This function returns the next state; it is not an event handler.", "Spread inside a new array literal copies entries into that array. It does not mutate the original outer array."]}, {"id": "callbacks", "title": "Props and callbacks", "subtitle": "Connect actions to shared state", "icon": "⇄", "color": "pink", "module": "shared-state", "exercise": "e07", "lab": "callbacks", "question": "q13", "diagram": "shared-state", "cheat": 6, "idea": "Keep shared state in the parent. Give the child a function it can call to request a change. The parent updates state and passes new values down.", "takeaway": "Pass the function as a prop. Call it later, inside the event handler, with the expected argument.", "example": "// Parent component fragments:\nconst addItem = draft => {\n  setMenu(previous => [...previous, draft]);\n};\n<Composer onAdd={addItem} />\n\n// Child JSX fragment:\n<Button title=\"Add\"\n  onPress={() => onAdd({ name, popular })} />", "steps": [[[1, 2, 4], "The parent owns menu and the callback. It passes the function itself to Composer through onAdd."], [[7, 8], "The child passes an arrow function to onPress. On a press, that arrow calls onAdd with an object."], [[2], "The parent requests the next array, and React renders again. This simplified fragment omits ID creation; the full app includes it."]], "prompt": "Sketch a parent with menu state and a child with draft text. Write the callback prop and the child’s onPress expression. Explain who owns the array.", "hint": "The child gets onAdd as a prop. Its press handler should call onAdd with a { name, popular } object.", "solution": "// JavaScript + JSX example. E07 adds TypeScript types.\nimport { useState } from 'react';\nimport { Button, Switch, Text, TextInput, View } from 'react-native';\n\nexport default function Menu() {\n  const [menu, setMenu] = useState([]);\n  const addItem = draft => {\n    setMenu(previous => [...previous, draft]);\n  };\n  return (\n    <View>\n      <Text>{menu.length} items<\/Text>\n      <Composer onAdd={addItem} />\n    <\/View>\n  );\n}\n\nfunction Composer({ onAdd }) {\n  const [name, setName] = useState('');\n  const [popular, setPopular] = useState(false);\n  return (\n    <View>\n      <TextInput value={name} onChangeText={setName} />\n      <Switch value={popular} onValueChange={setPopular} />\n      <Button title=\"Add\"\n        onPress={() => onAdd({ name, popular })} />\n    <\/View>\n  );\n}", "explain": "Menu owns the array. Composer owns the draft name and popular values, receives onAdd as a prop, and calls it on a press. The parent appends the draft with a pure updater, so the item count changes on the next render. This sketch isolates ownership and callback wiring; E07 adds TypeScript contracts, and the full app adds validation and stable IDs for rendered items.", "quiz": "When is addItem called here?", "quizcode": "<Button title=\"Add\"\n  onPress={() => addItem({ name, popular })} />", "options": ["While the component renders.", "When the button is pressed.", "Only when the component first mounts."], "correct": 1, "responses": ["Rendering creates and passes the arrow function. It does not call addItem yet.", "React Native calls the handler on a press. The handler calls addItem with the current draft values.", "This is an event handler, not a mount effect. It runs when the button is pressed."]}, {"id": "types", "title": "TypeScript inference", "subtitle": "Add types where they help", "icon": "T", "color": "purple", "module": "typescript-data", "exercise": "e08", "lab": null, "question": "q05", "diagram": "typescript-data", "cheat": 2, "idea": "TypeScript can infer many types from values you supplied. Add a type when the starting value does not describe all the values you intend to store.", "takeaway": "Typed initial data guides inference. Empty arrays, null, and callback contracts often need explicit types.", "example": "type Item = { name: string; popular: boolean };\nconst initialItems: Item[] = [{ name: 'Tea', popular: false }];\n\n// These hooks belong inside a component:\nconst [menu, setMenu] = useState(initialItems);\nconst [emptyMenu, setEmptyMenu] = useState<Item[]>([]);\nconst [selected, setSelected] = useState<Item | null>(null);", "steps": [[[0, 1], "Item describes the object shape. initialItems already has the array type Item[]."], [[4], "useState can infer Item[] from the typed initial value. Another annotation here would usually be redundant."], [[5, 6], "The empty array does not describe its future items, and null does not describe a future selection. Explicit types explain both intentions."]], "prompt": "Define MenuItem with name and popular. Type an empty menu array and an onAdd callback prop that receives one MenuItem.", "hint": "An array type is MenuItem[]. An action callback can have the type (item: MenuItem) => void.", "solution": "type MenuItem = { name: string; popular: boolean };\ntype Props = { onAdd: (item: MenuItem) => void };\n\n// Inside a component, with useState imported:\nconst [menu, setMenu] = useState<MenuItem[]>([]);", "explain": "The state type tells TypeScript which elements may be added later. The prop type tells the child what argument to pass. void means the caller does not use the action callback’s return value.", "quiz": "With TypeScript strict checking enabled, which type permits no selection now and an Item later?", "quizcode": "// Item is already defined. Choose the state type.", "options": ["useState(null)", "useState<Item | null>(null)", "useState<string>(null)"], "correct": 1, "responses": ["With strict typing, null alone does not describe a future Item. Give the state the intended union type.", "Item | null describes both possibilities. Check for null before using the selected Item’s properties.", "null is not a string under strict null checks, and string would not describe the intended Item."]}];
window.STUDY_SEARCH = [{"title": "Understand the data before writing the screen", "url": "concepts.html#typescript-data", "category": "Concept", "terms": "typescript-data Understand the data before writing the screen Describe the difference between a value and its type. Read object, array and function types without guessing. Use inference when it is informative and annotations when they are needed. JavaScript runs the program and TypeScript checks its shape The code that runs on the device is JavaScript. TypeScript adds a system for describing the kinds of values your program expects. A number can be added to another number; a menu item is an object with named fields; an array is an ordered collection. A type checker can catch many mismatches before you run the app. It cannot prove that your layout is attractive, that a timer is cleaned up, or that an answer from a server is trustworthy. Think in two passes when you are under time pressure. First describe the operation in plain JavaScript: “Make a new array that contains the old items and this new item.” Then check the boundary types: “The input is one MenuItem; the state is an array of MenuItem.” This separates the operation from the type annotation. It does not mean deleting every type annotation or silencing errors with any. TypeScript type annotations are normally removed when the project is transformed into JavaScript. If a variable is declared as number, does TypeScript convert the text \"12\" into the number 12? No. Types describe expectations; they do not perform conversions. Number(\"12\") performs a runtime conversion. A numeric keyboard also does not change TextInput text into a number. types-to-runtime Read an object and an array as different structures An object groups fields that describe one thing. An array groups many things in a particular order. In this guide, a MenuItem has an id, a name and a popular flag. The id provides stable list identity; some smaller examples need only name and popular. Keep the required shape consistent within any one exercise. Use item.name when you want a field of one object. Use menu[0] when you want the first element of an array. Use menu.length when you want the number of elements. A type ending in [] means an array of values of that type. MenuItem[] is not the same shape as MenuItem, and an object with numeric property names is not an array. Dot notation and bracket notation can read the same property: item.name and item[\"name\"] both read the name field. Bracket notation is also useful when a variable holds the property name, provided TypeScript knows that key is valid. A const binding cannot be reassigned, but const does not freeze an object or array; you still need the immutable-update discipline for React state. // Standalone TypeScript data example.\ntype MenuItem = {\n  id: string;\n  name: string;\n  popular: boolean;\n};\nconst item: MenuItem = { id: 'tea', name: 'Tea', popular: true };\nconst menuItems: MenuItem[] = [item];\nconsole.log(item.name);        // Tea\nconsole.log(menuItems.length); // 1\nconsole.log(menuItems[0].popular); // true tsx Square brackets create an array. Curly braces create an object in expression position. Changing the brackets changes the data structure, not just the appearance of the code. Let useful initial values do some of the typing Inference means TypeScript works out a type from evidence in the surrounding code. If menuItems is already declared as MenuItem[], useState(menuItems) can infer the state type. Similarly, useState(0) gives number state and useState(\"\") gives string state. Repeating the same type is allowed, but it is not always necessary. An empty array does not tell the checker what future elements will look like. In a strict React TypeScript project, useState([]) commonly infers never[], which rejects added objects. Supply useState<MenuItem[]>([]) when you start empty. If a selected item may be absent initially and later hold an object, write useState<MenuItem | null>(null). The vertical bar means either alternative is permitted. You still need to check for null before reading its properties. // Fragment inside a component; import useState from react.\n// MenuItem and menuItems are defined in the preceding example.\nconst [menu, setMenu] = useState(menuItems); // inferred MenuItem[]\nconst [emptyMenu, setEmptyMenu] = useState<MenuItem[]>([]);\nconst [selected, setSelected] = useState<MenuItem | null>(null);\nconst title = selected === null ? 'Choose an item' : selected.name; tsx Why is useState<MenuItem[]>([]) more useful than useState<any[]>([])? The explicit element type tells TypeScript what an item must contain. any allows mistakes such as appending a number or omitting a required field, so it removes a check that would help you debug. Use object destructuring and shorthand deliberately Destructuring reads named fields from an existing object into local variables. In const { name, popular } = item, no new menu item is created: name and popular are local bindings to values already stored on item. Object shorthand goes the other direction. If local variables are called name and popular, { name, popular } constructs the same fields as { name: name, popular: popular }. Props often use destructuring because a component receives one props object. Writing function ItemCard({ item }: ItemCardProps) means “take the item field from the props object, and check the whole props object against ItemCardProps.” It does not mean that item itself has the shape ItemCardProps. Say this sentence aloud before writing callback props; it prevents a common confusion between an item and a wrapper containing an item. // Standalone TypeScript example.\nconst source = { name: 'Rice', popular: false };\nconst { name, popular } = source; // read two fields\nconst copy = { name, popular };  // construct a new object\nconsole.log(copy.name); // Rice tsx Read function types as promises between pieces of code The type (item: MenuItem) => void says the caller must supply one MenuItem and should not use a return value. It is a good type for an onAdd prop whose job is to request a state change. By contrast, (item: MenuItem) => string describes a transformation that returns a string. These functions may take the same input but serve different roles. Annotate parameters of standalone functions when TypeScript has no context from which to infer them. In menu.map(item => item.name), the menu array already supplies the parameter type. In const label = item => item.name, the checker may have no such evidence. Do not assume inference means all parameter annotations are unnecessary. The word void describes a contract about ignoring a result; it is not a runtime command. // Type declarations; MenuItem is defined above.\ntype AddHandler = (item: MenuItem) => void;\ntype LabelMaker = (item: MenuItem) => string;\nconst label: LabelMaker = item => item.name;\nconst describe = (item: MenuItem): string => item.name; tsx https://www.typescriptlang.org/docs/handbook/type-inference.html https://www.typescriptlang.org/docs/handbook/2/everyday-types.html"}, {"title": "Make arrow functions feel predictable", "url": "concepts.html#arrow-functions", "category": "Concept", "terms": "arrow-functions Make arrow functions feel predictable Distinguish a function value from a function call. Translate an expression body into a block body with return. Recognize which callback arguments a component supplies. A function is a value that can be saved and passed An arrow function describes work that can be done later. The parameter is a placeholder for the value supplied when the function is called. In item => item.name, item is not the whole menu. It is whichever individual item the caller supplies on a particular call. The name is your choice; entry => entry.name would do the same work. You can store a function in a variable, pass it to another function, or pass it through a component prop. A callback is simply a function passed to some other code so that code can call it. map calls its callback while producing the new array. A Pressable calls its handler after a press. “Callback” tells you the relationship between the functions; it does not automatically mean asynchronous. // Standalone TypeScript example.\nconst double = (value: number) => value * 2;\nconsole.log(typeof double); // function\nconsole.log(double(4));     // 8\nconst saved = double;       // save the function itself\nconsole.log(saved(5));      // 10 tsx function-value-call The two return forms have the same result With an expression body, the expression after => becomes the return value. With a block body, braces introduce a sequence of statements, and you must write return if you want a result. Parentheses around an expression can make a multiline JSX expression easier to read; they are not the thing that makes it return. The absence of a block body is what gives the implicit return. Before debugging a map, point at the arrow and ask, “Does this arrow return an expression, or open a block?” If it opens a block, find the return statement. The line breaks do not determine the answer. A one-line function with braces still needs return, and an expression-body function may span several lines. // Standalone TypeScript example.\nconst a = (x: number) => x * 2;\nconst b = (x: number) => { return x * 2; };\nconst c = (x: number) => { x * 2; }; // intentionally wrong for mapping\nconsole.log(a(3)); // 6\nconsole.log(b(3)); // 6\nconsole.log(c(3)); // undefined tsx Putting return on a line by itself can trigger JavaScript automatic semicolon insertion. Write return ( on the same line when returning multiline JSX. Does x => { x + 1; } return x + 1? No. It evaluates x + 1 and discards the result. Use x => x + 1 or x => { return x + 1; }. Return an object by making the expression explicit Curly braces directly after an arrow are read as a function body. To return an object with the expression form, wrap the object literal in parentheses: name => ({ name }). A block with an explicit return works too. This resolves the shortened-syntax puzzle raised in Lecture 2a: an arrow can return an object, but bare braces are ambiguous in that position. Arrays do not have this ambiguity. item => [item] clearly returns an array. This distinction is important when constructing new state. prev => [...prev, item] returns a new array; prev => ({ ...prev, item }) returns an object; prev => { ...prev, item } is not a valid array update. // Standalone TypeScript example.\nconst makeA = (name: string) => ({ name, popular: false });\nconst makeB = (name: string) => {\n  return { name, popular: false };\n};\nconsole.log(makeA('Soup').popular); // false\nconsole.log(makeB('Soup').name);    // Soup tsx Pass a handler now and let the event call it later If a handler already accepts the arguments you need, pass it directly. onPress={handlePress} passes a function. onPress={handlePress()} calls that function while rendering and passes its return value, which is usually undefined. If the call changes state, doing it during render can cause repeated renders. Use a wrapper when you need to provide your own argument. onPress={() => onAdd(item)} gives Pressable a no-argument wrapper whose body calls onAdd with a MenuItem. Pressable supplies a press event to its handler; it does not know that your application wants to add a menu item. The wrapper translates from a UI event to your application action. // JSX fragments; handlePress, onAdd and item are already defined.\n<Pressable onPress={handlePress}><Text>Open<\/Text><\/Pressable>\n<Pressable onPress={() => onAdd(item)}><Text>Add<\/Text><\/Pressable>\n// Avoid: onPress={onAdd(item)}. That calls onAdd while rendering. tsx Render: create a wrapper function and give it to Pressable. Press: Pressable calls the wrapper. Wrapper: call onAdd(item) with the intended item. Parent handler: request the state update. Practice the punctuation without memorizing a screenshot Write a function that doubles a number in both forms, then a function that returns an object in both forms. Next write the same transformation as a map callback. Finally place a handler in onPress. The words and data should change each repetition so that you learn the roles of the brackets rather than the appearance of one example. When explaining your code, name the input, the time of the call and the result. For example: “map calls this function once for each menu item now, and it returns a card element.” Then: “Pressable calls this other function later, and it asks the parent to add an item.” These short explanations expose misunderstandings before they become a screen full of syntax errors. Is every arrow function a callback? No. An arrow is a way to write a function. It is a callback when you pass it to other code to be called by that code. "}, {"title": "Read a screen as a tree of components", "url": "concepts.html#jsx-components", "category": "Concept", "terms": "jsx-components Read a screen as a tree of components Choose a suitable React Native component. Pass data through typed props. Use JavaScript expressions and conditional rendering inside JSX. JSX describes what the interface should contain A component is a function that returns a description of UI. React calls it to work out what should be displayed. JSX lets you express that description with nested tags. The nesting shows a tree: a View may contain a heading Text and several item cards. JSX is JavaScript syntax, not an HTML page embedded in your app. In TypeScript files that contain JSX, use the .tsx extension. Tags with capitalized names refer to components. Import View and Text from react-native rather than writing web tags such as div or p. Close every tag. A component can return one enclosing element or a fragment, written <>...<\/>, containing siblings. A fragment groups elements without creating another native layout box. // Complete small React Native component file.\nimport { Text, View } from 'react-native';\nexport default function Welcome() {\n  const name = 'CS 147L learner';\n  return (\n    <View>\n      <Text>Welcome, {name}<\/Text>\n      <Text>Explain your next step aloud.<\/Text>\n    <\/View>\n  );\n} tsx component-tree Use braces to insert an expression In JSX, quoted text is a literal string. A pair of braces lets you insert a JavaScript expression: a variable, a function value, a calculation, or the result of map. For a prop, title=\"Menu\" passes a fixed string, while title={screenTitle} reads the value of a variable. style={{ padding: 16 }} contains two different pairs of braces: the outer pair enters JavaScript, and the inner pair creates a style object. You cannot place an if statement directly inside JSX braces because if is a statement, not an expression. Compute a variable before return, use a ternary expression, or use a boolean condition with &&. Keep the condition actually boolean; 0 && <Text>Items<\/Text> evaluates to 0, so count > 0 is clearer and avoids accidentally rendering a number. // JSX fragment inside a component with menu state.\n<View>\n  <Text>{menu.length} items<\/Text>\n  {menu.length === 0 ? <Text>No items yet.<\/Text> : <Text>Ready to order.<\/Text>}\n  {menu.length > 0 && <Text>Choose a favorite.<\/Text>}\n<\/View> tsx Why are there two opening braces in style={{ padding: 16 }}? The outer braces switch from JSX into a JavaScript expression. The inner braces are the object literal that holds the padding property. Choose core components for their jobs View is a general container for layout and backgrounds. Text displays text and supports nested Text when part of a sentence needs different styling. Image displays an image; remote images usually need an explicit width and height. ScrollView provides scrolling for a modest amount of content. Button gives a standard button through its title and onPress props. Pressable gives you control over the visual content and press response. TextInput accepts text, ActivityIndicator communicates loading, and Alert.alert opens a platform alert where supported. Alert is an API you call, not a component that you put in JSX. Do not hide a broken interaction behind decorative styling. First verify that a button invokes the handler and that a TextInput updates state, then make them look good. For very long lists, FlatList is a useful extension because it avoids rendering every row at once; it is not a substitute for understanding map. Nested Text can inherit text styling from an enclosing Text. In the example, the inner word keeps the outer bold weight and changes its color. This limited text inheritance differs from expecting a font style on a View to cascade through an arbitrary component tree. // JSX fragment; import Image and Text from react-native.\n<Image source={{ uri: 'https://reactnative.dev/img/tiny_logo.png' }}\n  style={{ width: 48, height: 48 }} accessibilityLabel=\"React Native logo\" />\n<Text style={{ fontWeight: 'bold' }}>\n  Menu <Text style={{ color: '#165DCE' }}>today<\/Text>\n<\/Text> tsx A prop is an input to a reusable component An ItemCard should not need to know where its item came from. Give it an item prop, and it can display one item from any appropriate list. Define the prop type, destructure the props object, and read its fields. Props are read-only inputs. A child should not change item.popular directly because that object may belong to its parent’s state. Custom components are useful when a visual pattern repeats or a piece of behavior has a clear responsibility. Extracting every single Text into a component can make a small exercise harder to follow. A good interview explanation is, “The parent owns the menu array; this card displays one item.” If the card needs to request a change, add a callback prop instead of giving it a second copy of the same state. // Complete reusable component file.\nimport { Text, View } from 'react-native';\ntype MenuItem = { id: string; name: string; popular: boolean };\ntype ItemCardProps = { item: MenuItem };\nexport default function ItemCard({ item }: ItemCardProps) {\n  return (\n    <View style={{ padding: 12 }}>\n      <Text>{item.name}<\/Text>\n      {item.popular && <Text>Popular<\/Text>}\n    <\/View>\n  );\n} tsx key is a special React list attribute, not an ordinary prop delivered to the child. Pass item.id or a separate id prop if the child needs that value. Make disabled and empty states explicit Conditional UI is part of the application behavior. A sold-out button should be disabled as well as visually different. A list with zero items should explain the empty state. A loading operation should give feedback rather than leaving an apparently frozen screen. Use the same underlying state to determine both the label and the interaction so they cannot contradict each other. When testing a screen, try the boundary values: zero items, one item, a long name and several repeated presses. These often reveal a mistaken condition or missing layout constraint faster than the ordinary case. Explain the reason for your condition instead of reading it aloud: “The action requires stock, so the button is disabled when stock is zero or less.” // JSX fragment; stock and buy are defined by the component.\n<Button\n  title={stock > 0 ? 'Buy one' : 'Sold out'}\n  disabled={stock <= 0}\n  onPress={buy}\n/> tsx "}, {"title": "Understand state as a sequence of renders", "url": "concepts.html#state-snapshots", "category": "Concept", "terms": "state-snapshots Understand state as a sequence of renders Explain why a local variable cannot drive a persistent interactive screen. Predict direct and functional updates. Keep state update functions pure. A render receives a snapshot Each time React calls a component, the function reads the state values for that render and produces UI. Ordinary local variables are recreated when the function runs again. Changing a local variable also does not tell React to update the screen. A module-level variable may survive function calls, but changing it still does not notify React, and it can be accidentally shared by multiple component instances. useState gives you the current value and a setter. The setter asks React to compute a later render with a new state value. It does not rewrite the local binding in the currently running handler. That is why const [count, setCount] is correct: count itself is not reassigned. A later call to the component gets a new count binding. // Complete small React Native component file.\nimport { useState } from 'react';\nimport { Button, Text, View } from 'react-native';\nexport default function Counter() {\n  const [count, setCount] = useState(0);\n  return (\n    <View>\n      <Text>{count}<\/Text>\n      <Button title=\"Add one\" onPress={() => setCount(c => c + 1)} />\n    <\/View>\n  );\n} tsx render-snapshots A setter accepts a value or a pure updater function React permits both a next value and an updater function. Lecture 5a slide 10 teaches both forms. Passing an arrow function to a setter is therefore valid when that function computes the next state. If an array update fails, inspect what the function returns before concluding that the function itself is forbidden. For array state, setMenu([...menu, item]) is a valid direct update. setMenu(previous => [...previous, item]) is a valid functional update and is the clearer default when the new value depends on the previous value. The updater receives the pending state and must return the next state of the same type. It should not send a message, increment an external ID counter, or modify the old array. // Fragments inside a component; menu is MenuItem[] and item is MenuItem.\nsetMenu([...menu, item]); // direct replacement using this render's menu\nsetMenu(previous => [...previous, item]); // replacement from pending state\n// These are alternatives. Do not execute both to add one item. tsx Was the idea of passing menu => ... to the setter inherently wrong? No. Passing a pure updater is supported. The updater must return the correct next array, for example previous => [...previous, item]. Predict two queued updates before trying them Suppose the current render has count equal to 0. Two calls to setCount(count + 1) both calculate the number 1 from that same snapshot. They request the same replacement value, so the next count is 1. Two calls to setCount(c => c + 1) queue two transformations. The second receives the result of the first, so the next count is 2. This is a reasoning exercise about values and functions. You do not need to memorize a vague rule that setters are “slow.” Ask whether each call supplies a value computed now or a function to compute from pending state. React normally batches updates during a handler, which is why several setter calls do not mean several immediate visible screen changes. // Two alternative event handlers when the current count is 0.\nconst replaceTwice = () => {\n  setCount(count + 1);\n  setCount(count + 1);\n}; // next count: 1\nconst incrementTwice = () => {\n  setCount(c => c + 1);\n  setCount(c => c + 1);\n}; // next count: 2 tsx Direct case: calculate 0 + 1 twice, then queue replace-with-1 twice. Updater case: start at 0, apply +1 to get 1, then apply +1 to get 2. In both handlers, reading count immediately still reads the current snapshot. Store the minimum information that needs memory If a value can be calculated from current props or state, usually calculate it while rendering. For example, menu.length already tells you the number of items. Keeping a separate itemCount state creates a second value that must remain synchronized. You could add an item correctly but forget to update the count. Use separate state for independent facts, such as the draft name currently being typed and the list of saved items. When one is derived from another, prefer a calculation. This also makes the interview explanation simpler: “The displayed total is computed from the array, so it always matches.” Effects are not required to keep a derived count in sync. // Fragment inside a component that already owns menu state.\nconst itemCount = menu.length;\nconst popularCount = menu.filter(item => item.popular).length;\n// Both are recalculated from the current menu during rendering. tsx Read old logs and development repeats correctly If you log count immediately after setCount, the log shows the count from that render. To predict the next value for a simple direct update, compute it in a local variable before calling the setter. Do not try to await setCount: it does not return a Promise that resolves when rendering finishes. In development Strict Mode, React can call component bodies or updater functions extra times to expose accidental side effects. A pure updater still has the same intended result because it only calculates a value. If a repeated development call duplicates a network request or changes an external counter, the function is doing more than a state calculation. Fix that impurity rather than relying on the updater being called exactly once. The sample counter on Lecture 3a slide 11 and Lecture 3b slide 13 uses a setter name that does not match its declaration. In your code, use setCount when the hook declares [count, setCount]. https://react.dev/reference/react/useState https://react.dev/learn/queueing-a-series-of-state-updates"}, {"title": "Turn an array into a visible list", "url": "concepts.html#map-lists", "category": "Concept", "terms": "map-lists Turn an array into a visible list Trace the input and result of map. Return one element for each item. Choose stable keys and distinguish map from filter. Map transforms values and returns a new array For each present element in an ordinary dense array, map calls your function and collects its return value. The callback receives the current element, and may also receive its index and the original array. In [2, 4, 8].map(n => n * 3), the callback is called with 2, then 4, then 8. The returned values become [6, 12, 24]. The original numbers remain unchanged. The transformation can return numbers, strings, objects or React elements. This is why map is useful for rendering: your data array is the input, and an array of element descriptions is the result. map does not display anything by itself. React sees those elements only when you include the resulting array in the JSX that the component returns. // Standalone TypeScript example.\nconst prices = [2, 4, 8];\nconst labels = prices.map(price => `$${price.toFixed(2)}`);\nconsole.log(labels); // ['$2.00', '$4.00', '$8.00']\nconsole.log(prices); // [2, 4, 8] tsx map-pipeline Write both rendering forms and explain the return The expression form is convenient for a simple card. The block form is useful when you want to calculate a label or inspect a value before returning the element. Both forms produce the same kind of result. In either form, return the element you want React to render. A block that contains JSX but has no return produces undefined for that item. You may assign the result to a variable or place map directly inside JSX braces. Start with a named variable if it helps you separate transformation from display. Once that is comfortable, the inline version is a shorter way to write the same idea. // Fragment inside a component; menu and ItemCard are already defined.\nconst cards = menu.map(item => (\n  <ItemCard key={item.id} item={item} />\n));\nconst sameCards = menu.map(item => {\n  return <ItemCard key={item.id} item={item} />;\n});\n// Render one of these arrays, not both:\nreturn <ScrollView>{cards}<\/ScrollView>; tsx Why can a list contain no visible cards even though menu.length is 3? One possible cause is a block-body map callback with no return. It produces three undefined values, so React has no card elements to display. Also check that the result is included in returned JSX. Use a stable key to preserve identity React uses key to match sibling list elements across renders. A stable unique item ID lets React recognize that an existing item has moved or that a different item was deleted. Place the key on the outermost element returned by the map callback. If you return a View containing ItemCard, the View needs the key. An array index can be misleading when items are inserted, removed or reordered because the same position may now refer to a different item. A random value generated during rendering is worse: it changes identity every render. For these exercises, assign IDs when data is created and keep them with the items. Names are safe keys only when you can guarantee that they are unique and never change. // JSX fragment showing the key on the returned outer element.\n{menu.map(item => (\n  <View key={item.id} style={{ marginBottom: 8 }}>\n    <ItemCard item={item} />\n  <\/View>\n))} tsx A warning about a missing key is different from a missing-return bug. Adding a key does not make an undefined return value become a card. Separate selection from transformation filter answers, “Which elements should remain?” Its callback returns true to keep an item and false to leave it out. map answers, “What value should each element become?” Its callback returns the replacement value. To show only popular items, filter first and then map the selected items into cards. Neither method should mutate objects stored in state. map returns a new outer array, but a callback can still modify an existing item if you write item.popular = true. A safe transformation returns a new object for a changed item. The next lesson explains why both the array and the changed object need attention. // JSX-producing fragment; menu and ItemCard are defined.\nconst popularCards = menu\n  .filter(item => item.popular)\n  .map(item => <ItemCard key={item.id} item={item} />); tsx Debug a list by following the data once First inspect the array: is it empty, and do the fields have the names you expect? Next inspect the callback: does it return the intended element? Then inspect the returned JSX: is the result actually inserted? Finally check the component and layout: is the text visible, and can the screen scroll? This sequence tests distinct possibilities instead of repeatedly changing punctuation at random. Explain one item all the way through the process. “This object has name Tea. map passes that object to the callback. The callback returns ItemCard with that object as its item prop. ItemCard renders item.name inside Text.” If you can narrate that chain without looking at the answer, you understand the list rather than recognizing a snippet. What does [1, 2].map(x => { x * 2; }) produce? It produces [undefined, undefined]. The block evaluates multiplication but never returns its result. "}, {"title": "Build the next array without changing the old one", "url": "concepts.html#immutable-updates", "category": "Concept", "terms": "immutable-updates Build the next array without changing the old one Choose array or object spread according to the value shape. Append, insert, replace and remove without mutation. Explain shallow copies and state reference checks. Start with the shape of the next state If menu state holds MenuItem[], the next state must also be an array of menu items. The expression [...previous, item] creates that array: it expands the old elements into a new array and puts the new item after them. The surrounding square brackets are essential. The spread operator does not decide the container type; the surrounding syntax does. An object update uses braces instead: { ...item, popular: true } copies fields into a new object and overwrites the popular field. An array of objects often needs both forms, but at different levels. Read the syntax from the outside inward: “new array containing new or existing item objects.” This is more reliable than remembering a string of punctuation. // Standalone TypeScript example.\nconst oldNames = ['Tea', 'Rice'];\nconst newNames = [...oldNames, 'Soup'];\nconsole.log(oldNames); // ['Tea', 'Rice']\nconsole.log(newNames); // ['Tea', 'Rice', 'Soup']\nconst oldItem = { name: 'Tea', popular: false };\nconst newItem = { ...oldItem, popular: true };\nconsole.log(oldItem.popular); // false\nconsole.log(newItem.popular); // true tsx immutable-reference References explain why mutation is dangerous An array variable holds a reference to an array object. If you call menu.push(item), you change that same object. Passing the same reference back to the setter can be treated as unchanged because React compares state with Object.is. The deeper problem is that you have also changed data belonging to an earlier render. Another component or closure may still refer to that object. A new array gives React a new reference and preserves the old array as a snapshot. This is not a claim that React can never render after mutation: some unrelated update might cause a render and reveal the mutation later. That makes mutation bugs confusing. The reliable rule is to avoid modifying arrays and objects already stored in state. push returns the new numeric length of the array. setMenu(menu.push(item)) both mutates the old array and passes a number where an array is expected. Append and prepend with an updater When an operation depends on previous state, use the updater form. React supplies the pending array to your function, and your function returns a fresh array. The name previous is just a parameter name, not a special React keyword. You can call it current or items, but choose a name that makes the data flow obvious. Keep the updater pure. Construct a new item, including any generated identity, in the event handler before passing it into the updater. The updater should only calculate the next array. This keeps the code safe if React invokes an updater again during development checks. // Alternative fragments inside a component, with item: MenuItem.\nsetMenu(previous => [...previous, item]); // append\nsetMenu(previous => [item, ...previous]); // prepend\nsetMenu([]); // clear: the next state is known directly tsx Understand slice by following the boundary slice(start, end) copies a segment without changing the source. The end position is excluded. To insert an item at index 2, combine the part before index 2, the new item and the part beginning at index 2. To replace index 2, skip that old element by starting the suffix at index 3. To delete it, keep both surrounding pieces and omit the replacement. Write down the indexes for a small example before coding. For [A, B, C, D], index 2 refers to C. The prefix slice(0, 2) contains A and B. The suffix slice(2) contains C and D, while slice(3) contains only D. The one-character difference determines whether you insert or replace. splice has a similar name but mutates the original array. // Standalone TypeScript examples.\nconst values = ['A', 'B', 'C', 'D'];\nconst inserted = [...values.slice(0, 2), 'X', ...values.slice(2)];\nconst replaced = [...values.slice(0, 2), 'X', ...values.slice(3)];\nconst removed = [...values.slice(0, 2), ...values.slice(3)];\n// inserted: A B X C D; replaced: A B X D; removed: A B D tsx Copy the changed object as well as the array Spreading an array is a shallow copy. The new array initially contains references to the same item objects. If you create copy = [...menu] and then set copy[0].popular = true, you have still changed the original first object. Copy the object you change, and reuse unchanged objects. map is useful for replacing one item by ID. filter is useful for removing an item by ID. An ID-based update describes the item you mean even if its position has changed. The ternary below returns a new object for the matching item and the existing object for all others. React gets a new array, and the changed item gets a new object reference while keeping its stable id. // Fragments inside a component; targetId is a string.\nsetMenu(previous => previous.map(item =>\n  item.id === targetId ? { ...item, popular: !item.popular } : item\n));\nsetMenu(previous => previous.filter(item => item.id !== targetId)); tsx Does [...menu] make an independent deep copy of every MenuItem? No. It copies the array, but each element still refers to the same object. Create a new object for any item whose fields you change. https://react.dev/learn/updating-arrays-in-state"}, {"title": "Connect a form to its parent with callback props", "url": "concepts.html#shared-state", "category": "Concept", "terms": "shared-state Connect a form to its parent with callback props Choose the component that owns shared state. Control TextInput with value and onChangeText. Trace an event from child to parent and the updated data back down. Put shared state at the nearest common owner Suppose one component displays a menu and another component creates a new item. Both need access to the saved menu, so keep that array in their closest common parent. The parent passes data down through props. It also passes a function that a child may call to request a change. The child does not directly assign to the parent’s state. This is called lifting state up. It avoids two separate arrays that can disagree about what was added. A child may still own draft text if no sibling needs it. The question is not “Must all state be at the top of the app?” It is “Which components must agree on this value?” Choose the lowest common owner that can coordinate them. callback-data-flow A controlled input displays the state you give it TextInput uses value for the displayed string and onChangeText for a callback receiving the new string. In a controlled input, the value comes from React state. When the user types, the callback requests a state update. The later render passes the updated value back into TextInput. If you provide value but never update it, typing may appear to be ignored because the displayed value remains the old string. onChangeText is especially convenient because it passes text directly. It differs from onChange, which supplies an event object. Do not write event.target.value when using React Native onChangeText. If you need to trim a submitted name, do that at submission time; trimming on every keystroke can make ordinary typing awkward. // Complete small React Native component file.\nimport { useState } from 'react';\nimport { Text, TextInput, View } from 'react-native';\nexport default function DraftName() {\n  const [name, setName] = useState('');\n  return (\n    <View>\n      <Text>Item name<\/Text>\n      <TextInput value={name} onChangeText={setName}\n        placeholder=\"For example, Tea\" accessibilityLabel=\"Item name\" />\n      <Text>You typed: {name}<\/Text>\n    <\/View>\n  );\n} tsx User types a character. TextInput calls onChangeText with the new string. setName requests a render with that string. The next render passes name back through value. Define the callback contract before its implementation For a child that collects a name and a popular flag, use an onAdd callback that accepts those fields. This guide calls that input MenuDraft. The parent can add an id later when it creates the saved MenuItem. Separating the draft from a saved item is a useful design choice. An exercise may instead ask the child to provide the whole MenuItem. The function prop type is the agreement between parent and child. If onAdd expects one object, the child calls onAdd({ name, popular }); it does not call onAdd(name, popular). The braces construct one argument containing two fields. TypeScript can catch this mismatch before you press the button. // Type declarations for the next example.\ntype MenuDraft = { name: string; popular: boolean };\ntype ComposerProps = { onAdd: (draft: MenuDraft) => void }; tsx Build a child that requests a change The complete child below owns its draft string. It trims the name before submitting, ignores an empty draft, calls the parent’s onAdd function and clears the field. The button receives submit itself, so submission happens after a press. A more complex child could add a Switch for popular, but the callback relationship would be the same. The parent supplies the actual implementation of onAdd. This is why the child can be reused: one parent might add a menu item, while another might validate or log the draft. In a live interview, explain both sides. Saying “This button adds the item” is less precise than saying “This button calls the prop; the parent callback updates the array.” // Complete reusable child component file.\nimport { useState } from 'react';\nimport { Button, TextInput, View } from 'react-native';\ntype MenuDraft = { name: string; popular: boolean };\ntype ComposerProps = { onAdd: (draft: MenuDraft) => void };\nexport default function Composer({ onAdd }: ComposerProps) {\n  const [name, setName] = useState('');\n  const submit = () => {\n    const trimmedName = name.trim();\n    if (trimmedName.length === 0) return;\n    onAdd({ name: trimmedName, popular: false });\n    setName('');\n  };\n  return (\n    <View>\n      <TextInput value={name} onChangeText={setName}\n        accessibilityLabel=\"New item name\" />\n      <Button title=\"Add item\" onPress={submit}\n        disabled={name.trim().length === 0} />\n    <\/View>\n  );\n} tsx Follow the full round trip In the parent fragment below, the ID is supplied as part of an existing complete MenuItem. The key point is where the handler lives: it is defined in the component that owns menu. The parent gives the handler to a child as a prop. When the child calls it, the parent requests a new array, re-renders and supplies the updated list to its display children. “One-way data flow” does not mean a child can never send information to a parent. A child can call a callback with a value. The parent decides what state update follows, and the new state then flows down as props. A local state update in a child does not automatically re-render its ancestors. Avoid turning the lecture’s tree diagram into an absolute rule about all rendering; context and other subscriptions can also cause updates. // Parent fragment; MenuItem is defined and useState is imported.\nconst [menu, setMenu] = useState<MenuItem[]>([]);\nconst addMenuItem = (item: MenuItem) => {\n  setMenu(previous => [...previous, item]);\n};\n// Child receiving a complete MenuItem callback:\n// <ItemPicker onAdd={addMenuItem} />\n// Child event handler:\n// onPress={() => onAdd({ id: 'tea', name: 'Tea', popular: false })}\n// In a real list, enforce unique IDs if an item can be added repeatedly. tsx Where should saved menu state live if a Composer adds items and a MenuList displays them? In their closest common parent. The parent passes the array to MenuList and an add callback to Composer. Draft input state may remain inside Composer if only Composer needs it. "}, {"title": "Reason about spacing and Flexbox axes", "url": "concepts.html#layout", "category": "Concept", "terms": "layout Reason about spacing and Flexbox axes Distinguish padding, border and margin. Identify the container and direct children for each layout. Predict main-axis and cross-axis alignment in a row or column. Style objects describe each component React Native styles are JavaScript objects, usually written with camelCase property names such as backgroundColor and marginTop. StyleSheet.create groups named style objects and helps the type checker recognize supported properties. You apply one style with style={styles.card}. An inline object such as style={{ padding: 12 }} is also valid. You can combine styles in an array. Later entries override earlier values for the same property. This is useful for a selected or disabled state without copying every base style. Text styles, such as fontSize and color, belong on Text. A container’s text style does not work like a browser CSS rule that automatically cascades to all nested Text components. // Fragment with StyleSheet imported from react-native.\nconst styles = StyleSheet.create({\n  card: { padding: 16, backgroundColor: '#EAF3FF', borderRadius: 12 },\n  selected: { backgroundColor: '#C7F5DC' },\n  title: { fontSize: 20, fontWeight: '700', color: '#10233F' },\n});\n// JSX fragment: <View style={[styles.card, selected && styles.selected]} /> tsx The box model explains where space goes Content sits inside padding. The border surrounds the padded content. Margin creates space outside that border. If a card’s background should include the space around its text, use padding. If two cards need a gap between their outer edges, use margin or a container gap. These choices can look similar with no background, so draw the colored boxes when you are uncertain. Border styling uses properties such as borderWidth, borderColor and borderRadius. For a particular edge, use complete React Native property names such as borderTopWidth or borderLeftColor. A shorthand name from a slide or web CSS example may not be a valid React Native style. Numeric dimensions are density-independent units, not CSS strings ending in px. A card background should extend 16 units past its text on every side. Is that margin or padding? Padding. It lies inside the card border and background. Margin would add space outside the card. box-model Identify the main axis before naming an alignment Flexbox controls the direct children of a container. flexDirection chooses the main axis. In React Native the default is column, so the main axis is vertical and the cross axis is horizontal. With flexDirection: \"row\", the main axis is horizontal and the cross axis is vertical. justifyContent distributes children along the main axis. alignItems aligns them along the cross axis. Do not memorize “justifyContent means horizontal” because it fails as soon as direction changes. Instead say, “This is a row, so justifyContent controls horizontal distribution.” center packs children toward the center; space-between leaves space between the first and last items while placing them at the ends of the available main-axis space. alignSelf lets an individual child override the container’s cross-axis alignment for itself. // Style object for a horizontal row of items.\nconst rowStyle = {\n  flexDirection: 'row' as const,\n  justifyContent: 'space-between' as const,\n  alignItems: 'center' as const,\n  padding: 16,\n}; tsx flexbox-axes Size the container before distributing free space Alignment becomes visible only when the container has space to distribute. flex: 1 commonly lets a child expand into available space within a sized parent. Fixed numeric dimensions give a specific size; percentage dimensions depend on the parent’s size. A child with height: \"100%\" cannot invent a useful height if the parent has no resolved height. In a row with equally eligible children, flex: 1 and flex: 2 can allocate remaining space in a one-to-two ratio, but explicit dimensions, minimum sizes, content and other flex rules can affect the result. React Native also differs from web defaults: flexDirection starts as column and flexShrink defaults to 0. Long content can therefore overflow unless you provide appropriate wrapping, shrinking or scrolling. The width examples in Lecture 2b mean different things: the default comes from normal layout rules, width: 200 requests a fixed width, width: \"100%\" uses the resolved parent width, and width: windowWidth uses a measured window width. A parent may be narrower than the window because of padding or a sidebar, so percentage and window-based widths are not interchangeable. // JSX fragment; View and Text are imported.\n<View style={{ flex: 1, flexDirection: 'row' }}>\n  <View style={{ flex: 1, backgroundColor: '#C7F5DC' }}>\n    <Text>One share<\/Text>\n  <\/View>\n  <View style={{ flex: 2, backgroundColor: '#D9DEFF' }}>\n    <Text>Two shares<\/Text>\n  <\/View>\n<\/View> tsx Build a two dimensional screen from nested groups For a profile screen, start with a vertical page container. Put the avatar and name in a horizontal row. Inside the name area, use another vertical container for title and subtitle. Put action buttons in a separate row. Each container controls its own direct children, so you can solve one small alignment problem at a time. Before coding, sketch boxes and label each group row or column. Identify which group expands and where scrolling belongs. ScrollView needs a bounded height, commonly obtained by making its ancestors fill the screen. Use contentContainerStyle to style the scrollable content inside it and style to style the ScrollView itself. This distinction is useful when content padding or minimum height seems to have no effect. nested-layout Check dimensions on a changing screen Lecture 2b introduces Dimensions.get(\"window\").width. That reads the current window dimensions at that moment. A layout calculated once at module scope may not react to rotation, split-screen resizing or font changes. For a component that must respond to window changes, useWindowDimensions is a useful official React Native hook. Prefer flexible layout for ordinary rows and columns instead of manually calculating every coordinate. Verify the screen at a narrow width and with a long label. Cross-platform layout is not finished when it looks correct in one browser preview. Text metrics, safe areas, keyboards and available space can differ across devices. // Fragment inside a component; import useWindowDimensions from react-native.\nconst { width } = useWindowDimensions();\nconst compact = width < 380;\n// Example JSX: <View style={{ padding: compact ? 12 : 24 }} /> tsx https://reactnative.dev/docs/flexbox https://reactnative.dev/docs/height-and-width https://reactnative.dev/docs/scrollview"}, {"title": "Know what React Native and Expo provide", "url": "concepts.html#platforms-expo", "category": "Concept", "terms": "platforms-expo Know what React Native and Expo provide Compare web, PWA, native and cross-platform approaches. Explain the distinct jobs of React, React Native and Expo. Plan a small cross-platform check instead of assuming identical behavior. Separate the three layers React supplies the component model, props, state and hooks. React Native connects that model to platform UI and device capabilities. Expo adds a framework, libraries and development tools around React Native. When you write useState, that is a React feature. When you render a native TextInput, that is a React Native component. When you use an Expo development workflow, Expo helps you run and build the application. The course uses Expo to reduce setup work so that you can focus on application behavior. Expo Snack is a convenient browser-based place to experiment, while an Expo project on your computer gives you files and development tooling. Expo Go can run projects that fit the native capabilities bundled into that app. A development build is needed when your project requires native capabilities beyond that bundled set. react-native-expo Compare approaches using requirements A browser-only web app is reachable through a URL and can be updated on the server. A progressive web app adds installability and selected platform integration where supported. A fully native app uses each platform’s own development stack and can access its APIs directly. Cross-platform frameworks let teams share substantial code while producing applications for more than one platform. These are tradeoffs rather than a simple quality ranking. A campus information page may work well as a web app. An application needing specific hardware integration or demanding platform behavior may require native capabilities. Shared code reduces duplicated implementation, but teams still need platform testing and may need platform-specific code. Capabilities of PWAs and frameworks change over time, so avoid memorizing a fixed list of everything a browser can never do. Does cross-platform mean every feature works identically on iOS, Android and web? No. It means substantial code can be shared. Platform APIs, interaction conventions and component support can differ, so you still test the platforms you intend to support. React Native is not just a webpage inside a phone The lecture groups several technologies under a broad cross-platform or hybrid category. For precision, React Native’s usual iOS and Android UI is built from native platform views; it is not simply an HTML page placed inside a WebView. Other cross-platform approaches have different rendering strategies. React Native web support maps components to web behavior through additional tooling. This explains why browser HTML and CSS examples need translation. A div becomes a View, visible text belongs in Text, and the style system supports React Native properties rather than every browser CSS feature. It also explains why browser preview is useful but not sufficient evidence that a mobile interaction works correctly. Test the parts users can feel For a small practice screen, test text entry, keyboard behavior, scrolling, button presses, long labels and narrow layouts. Add clear accessible labels to custom controls and preserve readable contrast. A pressable region should have enough space to activate comfortably. Check that disabled controls communicate why they are unavailable through surrounding text or labels when the reason is not obvious. Use a consistent primary platform during timed practice so that setup does not consume your interview time. Then run the same app on another supported platform and explain any differences. This gives you practical evidence for a cross-platform discussion while reinforcing the central syntax and state skills. Make a minimal app run before expanding it Open the course’s existing Expo environment or an appropriate TypeScript Snack. Verify a View and Text render. Add a button that changes a number. Only then add the list and child input. This creates a known working baseline and makes each new error easier to locate. Package versions and Expo SDK compatibility change. Follow the setup instructions for the actual course project rather than upgrading its dependencies immediately before an interview. Expo’s npx expo install selects package versions intended to work with the project’s Expo version. Knowing what the tool does is more valuable here than memorizing a global installation command. https://reactnative.dev/docs/intro-react-native-components https://docs.expo.dev/get-started/start-developing/ https://docs.expo.dev/develop/development-builds/introduction/"}, {"title": "Organize files and recover from errors aloud", "url": "concepts.html#modules-debugging", "category": "Concept", "terms": "modules-debugging Organize files and recover from errors aloud Match named and default imports to exports. Read the first useful error before changing code. Demonstrate an independent problem-solving process in 25 minutes. Match imports to the export form A file can have one default export and many named exports. Import a default export without braces; the importing file chooses its local name. Import a named export with braces and its exported name, unless you explicitly rename it with as. A package import names an installed dependency, while a relative import such as ./ItemCard names a local file. When a component cannot be found, inspect both files. Is the component exported? Is the import named or default? Does the path point to the correct location and match capitalization? These checks are often more useful than editing JSX. An unresolved module error is a different problem from passing the wrong prop type. A named import may be renamed locally with as: import { colors as palette } from \"./colors\". A namespace import gathers a module’s exported names under one object: import * as theme from \"./colors\" lets you access theme.colors. The import screenshots in the lecture show these alternatives. Changing the local name does not change the original export, and namespace imports do not make every imported value a default export. // File: types.ts\nexport type MenuItem = { id: string; name: string; popular: boolean };\n\n// File: ItemCard.tsx (outline of the export form)\n// export default function ItemCard(...) { ... }\n\n// File: App.tsx\nimport ItemCard from './ItemCard';\nimport type { MenuItem } from './types';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\n// Alternative forms for a module exporting a named colors value:\n// import { colors as palette } from './colors';\n// import * as theme from './colors'; // then use theme.colors tsx Classify the error before fixing it A syntax error means the language could not parse the code: perhaps a tag is unclosed or a block is missing its closing brace. A type error means the code’s described values do not fit: perhaps an object is supplied where an array is expected. A runtime error occurs while the program runs, such as reading a field of undefined. A behavior bug can have no error message at all, such as a button that runs too early or a list that does not update. Read the first useful error, locate the expression it points to and compare the expected and actual shape. Later errors can be consequences of the first one. Change one thing, run again and describe what changed. If you randomly replace several brackets, you lose evidence about which assumption was wrong. TypeScript says a number is not assignable to MenuItem[]. What should you inspect first? Inspect the expression being passed as the next array state. A common cause is menu.push(item), which returns a number rather than a new array. debugging-loop Use a short verbal debugging loop Say what you expected, what you observed and one hypothesis that could explain the difference. For example: “I expected a new row after pressing Add. The handler logs the draft, so the press works. I will inspect whether the setter returns a new array.” This shows the interviewer a reasoning process even while the code is incomplete. Test the smallest part that can settle the hypothesis. If the callback is never called, do not spend time on array spread yet. If the callback is called but the array stays unchanged, inspect the update. If the array changes but no row appears, inspect map and rendering. Every step should narrow the possibilities. Prepare to work within the course assessment rules Lecture 4a describes the initial coding interviews as 25-minute live programming tasks in Expo Snack, with a reference screenshot and a staged handout. It says the process matters and students are not expected to complete every part. These slides concern the first coding interview; they are useful practice context, but they do not establish the exact content or rules of every later assessment. The same slides permit general internet reference and, optionally, one page of handwritten English notes on both sides. They prohibit other AI tools apart from the stated search-summary exception and prohibit homework solutions or solution-like code, including handwritten copies. Treat this study kit as preparation, not an authorized interview aid. Confirm current assessment instructions with the course staff; do not carry its code-rich cheat sheet into the assessment as if it were approved. Allocate practice time to the observed gaps Spend the first few minutes reading requirements and identifying the data shape, state owner and repeated component. Build the smallest visible screen, then render initial data. Add a callback that performs one immutable update. Add the controlled input and connect it to the callback. Use the final minutes to test an empty input, a second addition and any requested condition. This sequence gives the core interaction enough practice time. Do not spend the first half of practice making the screen visually perfect while the parent-child interaction remains unimplemented. After each mock, write one sentence about the first place you became uncertain. Then isolate that operation for a five-minute drill before doing another full mock. A change of nouns in the next task helps reveal whether you learned the concept or only the previous answer. "}, {"title": "Use hooks and timers without creating hidden repeats", "url": "concepts.html#hooks-effects", "category": "Concept", "terms": "hooks-effects Use hooks and timers without creating hidden repeats Keep hook calls at the top level in a stable order. Choose an effect only for synchronization with an external system. Explain dependencies, cleanup and stale state in a timer. Hooks connect a component to React features useState and useEffect are hooks. For these hooks, call them at the top level of a function component or a custom hook, in the same order each render. Do not put them in a loop, event handler or conditional branch. If a component sometimes returns early, place its hooks before that conditional return so that their order remains consistent. The lecture says hooks must be called exactly once every render. The practical rule is more precise: each hook call site must occur in a consistent order for that component’s renders. A component may use several useState calls, and React may render the component more than once. A function name starting with use is a convention for hooks, not a magic permission to call it anywhere. // Fragment inside a component. Hooks remain unconditional.\nconst [running, setRunning] = useState(false);\nconst [seconds, setSeconds] = useState(0);\nuseEffect(() => {\n  if (!running) return;\n  // Start external synchronization here.\n}, [running]); tsx An effect synchronizes after a committed render An effect is appropriate when your component must keep an external system in step with its state, such as starting and stopping an interval. A button’s direct response belongs in its event handler. A value derived from other state usually belongs in a calculation during render. You do not need an effect to compute menu.length or to append an item immediately after a press. Timer callbacks execute later, after the current JavaScript work has finished and the delay allows them to run. setTimeout schedules one callback; setInterval repeatedly schedules callbacks until cleared. Delays use milliseconds, and actual execution can be later than the requested delay. A one-second interval is adequate for a learning counter but is not a guarantee of precise elapsed time. effect-lifecycle Read the dependency list as values React compares With no dependency argument, an effect runs after each commit of that component. With [], it sets up for a mount without re-running because of changed reactive dependencies. With [running], it also re-synchronizes after running changes. React compares each dependency with its previous value using Object.is; a newly created array containing the same dependency values does not by itself mean those values changed. List the reactive values that the effect reads. Do not choose [] merely to silence repeated runs if the effect actually depends on a changing prop. An effect that sets state on every render can cause a loop. The right fix is to understand what the effect synchronizes and when it should restart, not to suppress a warning blindly. If an effect depends on [running], should changing an unrelated draft string restart its interval? No. If running is unchanged, that dependency has not changed. A render caused by draft text alone does not require this effect to re-synchronize. Pair setup with cleanup The cleanup function undoes the resource established by that effect setup. For a timer, retain the ID returned by setInterval and return a function that calls clearInterval. React calls cleanup before the next setup when dependencies change and when the component is removed. An interval created in the component body would be created again on every render, producing multiple independent timers. In development Strict Mode, React can perform an extra setup-cleanup cycle as a check. Therefore “[] means exactly once forever” is not a safe mental model. Cleanup should make repeated setup and teardown harmless. The example below needs only running as a dependency because the functional updater reads pending seconds, not a seconds value captured by the effect. // Complete React Native learning timer component.\nimport { useEffect, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\nexport default function Timer() {\n  const [running, setRunning] = useState(false);\n  const [seconds, setSeconds] = useState(0);\n  useEffect(() => {\n    if (!running) return;\n    const id = setInterval(() => {\n      setSeconds(previous => previous + 1);\n    }, 1000);\n    return () => clearInterval(id);\n  }, [running]);\n  return (\n    <View>\n      <Text>{seconds} ticks<\/Text>\n      <Button title={running ? 'Pause' : 'Start'}\n        onPress={() => setRunning(value => !value)} />\n    <\/View>\n  );\n} tsx Initially running is false, so no interval is started. Press Start: running becomes true and the effect starts one interval. Each tick computes the next seconds from pending state. Press Pause: cleanup clears the old interval; the new setup starts none. Unmount: React also cleans up any active interval. Recognize a stale closure A callback keeps access to the values from the render in which it was created. If an interval created with [] repeatedly calls setSeconds(seconds + 1), and seconds was 0 in that render, it repeatedly requests 1. It does not automatically see future seconds values. The updater setSeconds(previous => previous + 1) asks React to supply pending state instead. This connects the later lecture to the earlier state lessons. Functional updates help express state changes safely when callbacks run later or several updates are queued. Practice explaining this connection after the core menu problem is comfortable. The supplied decks do not establish the exact questions in any particular assessment. An effect setup callback must not be an async function, because an async function returns a Promise rather than a cleanup function. If you need asynchronous work, define and call an inner async function and keep cleanup synchronous. https://react.dev/reference/react/useEffect https://react.dev/reference/rules/rules-of-hooks"}, {"title": "Follow asynchronous results without blocking the screen", "url": "concepts.html#promises", "category": "Concept", "terms": "promises Follow asynchronous results without blocking the screen Describe pending, fulfilled and rejected Promise states. Predict the ordering of immediate code and then callbacks. Return chained work and handle failure deliberately. A Promise represents a result that may arrive later A Promise is an object representing the eventual outcome of an operation. It starts pending and becomes fulfilled with a value or rejected with a reason. Once settled, its outcome does not change. You attach a fulfillment callback with then. The callback receives the fulfilled value; the Promise itself is not that value. This extends the callback ideas you already know. A timer accepts a callback when you schedule it. A Promise-returning operation gives you an object to which you attach a callback. Writing .then does not pause the surrounding function. Code after the registration continues, and the callback runs when the Promise can deliver its outcome. promise-timeline Predict the order of synchronous and queued work In the example, A prints immediately. Promise.resolve creates an already-fulfilled Promise, but its then callback is still scheduled to run after the current synchronous code. C therefore prints before B. This matters when you try to assign an asynchronous result to a local variable and use it immediately outside the callback: the value may not have arrived yet. To use the result in a screen, request a state update inside the fulfillment callback. React can then render the later value. A console log immediately after starting the operation is not evidence that the operation has already finished. Name the moment when each line can run. // Standalone JavaScript or TypeScript example.\nconsole.log('A');\nPromise.resolve('B').then(value => console.log(value));\nconsole.log('C');\n// Output: A, C, B tsx What does .then(callback) return? It returns a new Promise. The value returned by callback determines that new Promise’s fulfillment value, or its eventual outcome if callback returns another Promise. Return the result that the next step needs A then callback can transform the result. If it returns a normal value, the next then receives that value. If it returns another Promise, the chain waits for that Promise’s outcome. If the callback has a block body and forgets return, the next step receives undefined. This is the same expression-body versus block-body issue that caused trouble in map. The lecture focuses on attaching callbacks and receiving results. Rejection handling and chaining are useful related extensions. A throw in a then callback rejects the resulting Promise, and catch can handle rejection. A catch callback can itself return a recovery value or throw again. These details explain why swallowed errors or missing returns can make asynchronous code appear to succeed with no useful data. // Standalone Promise transformation example.\nPromise.resolve(3)\n  .then(value => value * 2)\n  .then(value => { return `Count: ${value}`; })\n  .then(message => console.log(message)) // Count: 6\n  .catch(error => console.error('Could not finish:', error)); tsx Model loading, success and failure in the UI When a result is not yet available, show a loading indicator or message. On success, display the data. On failure, display a useful error state and a deliberate try-again action if appropriate. A Promise rejected by an operation does not automatically create a readable error message on the screen. For a deterministic practice task, use a local Promise-based delay rather than a real service. This isolates callback timing from network availability. The delay function below is an invented teaching helper; setTimeoutAsync is not a built-in JavaScript API. Lecture 5b similarly introduces a hypothetical Promise-based timer to explain the pattern. // Standalone TypeScript helper, followed by usage.\nfunction waitForLabel(delayMs: number): Promise<string> {\n  return new Promise(resolve => {\n    setTimeout(() => resolve('Ready'), delayMs);\n  });\n}\nwaitForLabel(500).then(label => console.log(label));\nconsole.log('Waiting'); // prints before Ready tsx Know where the provided lectures stop Lecture 5b announces real fetching as the next topic, but that later lecture is not in the provided folder. Navigation, persistent storage and a full networking lesson are also absent from these ten decks. The core study sequence therefore covers the supplied Promise concepts without pretending these other topics were taught here. As related background, async/await is another way to consume Promises: an async function returns a Promise, and await pauses that function’s continuation while other work can continue. If you later use fetch, check HTTP status and validate the data shape; a TypeScript annotation does not validate a server response. Keep those extensions behind the core goals until you can explain map, state updates and callback props independently. A response to an earlier request can arrive after a newer request. If you extend practice to changing queries, use cleanup or cancellation/ignore logic so stale results do not replace the latest screen. This is beyond the supplied introductory Promise slides. "}, {"title": "Translate arrow functions without guessing", "url": "exercises.html#e01", "category": "Exercise", "terms": "e01 Translate arrow functions without guessing Essential arrow functions return objects This is a standalone TypeScript drill. Write each function in both expression-body and block-body form. First predict the results of triple(4), label(\"Tea\"), and makeItem(\"Tea\"). Then explain every pair of parentheses and braces out loud. const triple = (n: number) => { n * 3; };\nconst label = (name: string) => { return \"Item: \" + name; };\nconst makeItem = (name: string) => { name: name }; Return 12 from triple(4). Return \"Item: Tea\" from label(\"Tea\"). Return an object with name \"Tea\" from makeItem(\"Tea\"). Use no any types. A block body needs an explicit return when a result is required. An object expression begins with a brace, so wrap the object in parentheses in an expression body. Compare n => n * 3 with n => { return n * 3; }. // Standalone TypeScript.\nconst triple = (n: number) => n * 3;\nconst tripleBlock = (n: number) => { return n * 3; };\nconst label = (name: string) => \"Item: \" + name;\nconst labelBlock = (name: string) => { return \"Item: \" + name; };\nconst makeItem = (name: string) => ({ name });\nconst makeItemBlock = (name: string) => { return { name }; };\nconsole.log(triple(4), label(\"Tea\"), makeItem(\"Tea\")); The body after => is either one expression or a statement block. An expression body returns its value automatically. A block executes statements and needs return to provide a value. Without return, triple originally produced undefined. In the original makeItem, the braces start a block and name: is parsed as a label, not an object property. Parentheses make ({ name }) an object expression. The shorter property name form means { name: name }. The three printed values are 12, \"Item: Tea\", and { name: \"Tea\" }. Change the input to 0 and the empty string; the functions still return values. Rewrite all three without looking, then compare expression and block results. Write a function that returns { title, done: false } for a study task. Explain why => ({ ... }) works."}, {"title": "Repair a map that displays nothing", "url": "exercises.html#e02", "category": "Exercise", "terms": "e02 Repair a map that displays nothing Essential map JSX keys Repair this JSX fragment inside a component. Assume Text and View are imported from react-native. Explain what each invocation of the map callback receives and returns. Write both valid callback styles. const items = [{ id: \"a\", name: \"Tea\" }, { id: \"b\", name: \"Soup\" }];\nreturn (\n  <View>\n    {items.map(item => { <Text>{item.name}<\/Text>; })}\n  <\/View>\n); Display Tea and Soup in that order. Use a stable key from the data. Do not alter items or use a for loop. Inspect the callback return value, not only the JSX element. JSX braces insert an expression into the parent View. They are different from a function-body block. Use item => (<Text key={item.id}>{item.name}<\/Text>) or a block with return. // Component-body fragment; Text and View are imported.\nconst items = [{ id: \"a\", name: \"Tea\" }, { id: \"b\", name: \"Soup\" }];\nconst rows = items.map(item => (\n  <Text key={item.id}>{item.name}<\/Text>\n));\nreturn <View>{rows}<\/View>;\n\n// Equivalent map expression, used instead of the one above:\n// items.map(item => {\n//   return <Text key={item.id}>{item.name}<\/Text>;\n// }); map calls the callback for each present array element and gathers the returned values into a new array. Here the input elements are data objects; the returned values are React elements. The original callback returned undefined, so it supplied no text elements to display. The outer {rows} inserts the array into JSX. key helps React match siblings across changes. It belongs on the outermost element returned by this map, and a data ID is more stable than a changing position or a random number. Two text rows appear, with no missing-key warning. Reverse the input array; the rendered order reverses. Temporarily remove return from a block callback and explain the resulting empty display. Render a list of campus clubs using a custom ClubCard component instead of Text."}, {"title": "Make a counter update through React", "url": "exercises.html#e03", "category": "Exercise", "terms": "e03 Make a counter update through React Essential useState events state snapshots Build a complete App.tsx counter. The count starts at zero, Add increments once, Add three increments three times, and Reset sets zero. Explain why changing a local variable is insufficient. // Broken component-body fragment:\nlet count = 0;\nconst add = () => { count += 1; }; Use state at the top level of the component. Pass functions to onPress. Use three queued functional updates for Add three. A local variable is recreated when the component runs, and assigning it does not schedule a render. useState returns the current render value and a setter. Three calls to setCount(c => c + 1) compose; three calls to setCount(count + 1) use the same captured value. // Complete App.tsx.\nimport { useState } from 'react';\nimport { Button, Text, View } from 'react-native';\nexport default function App() {\n  const [count, setCount] = useState(0);\n  function addThree() {\n    setCount(c => c + 1);\n    setCount(c => c + 1);\n    setCount(c => c + 1);\n  }\n  return (\n    <View style={{ padding: 40 }}>\n      <Text>{count}<\/Text>\n      <Button title=\"Add\" onPress={() => setCount(c => c + 1)} />\n      <Button title=\"Add three\" onPress={addThree} />\n      <Button title=\"Reset\" onPress={() => setCount(0)} />\n    <\/View>\n  );\n} React retains state between renders. Calling its setter queues an update; the next render receives the next value. The count variable in the current handler remains the current render’s snapshot. A setter accepts either the next value or an updater function. Each updater receives the pending state after earlier queued updates. This is why three functional increments produce three additional counts. An updater should be pure: return the next value without changing external data. Start at 0; Add gives 1; Add three gives 4; Reset gives 0. Replace the three updater calls with setCount(count + 1); from 0 they produce 1. Explain before running. A log of count immediately after calling its setter still shows the current handler’s captured value. Build a ticket counter with a decrement button that never goes below zero."}, {"title": "Append without mutating the original array", "url": "exercises.html#e04", "category": "Exercise", "terms": "e04 Append without mutating the original array Essential array spread functional updates inference Repair this attempted update. This is a component-body fragment with useState imported. Show both a direct replacement and a functional update. Prefer the latter for the final add handler because the next menu depends on the previous menu. type MenuItem = { name: string; popular: boolean };\nconst initialMenu: MenuItem[] = [{ name: \"Tea\", popular: false }];\nconst [menu, setMenu] = useState(initialMenu);\nconst addMenuItem = (item: MenuItem) => {\n  setMenu(previous => { ...previous, item });\n}; Append to an array, not an object. Preserve the old array and its entries. Explain why TypeScript infers MenuItem[] here. The setter can accept an updater. Keep that idea and fix its returned value. Square brackets construct an array. Spread copies its elements into a new array. Return [...previous, item] with an expression body, or use a block with return. // Component-body fragment; useState is imported.\ntype MenuItem = { name: string; popular: boolean };\nconst initialMenu: MenuItem[] = [{ name: \"Tea\", popular: false }];\nconst [menu, setMenu] = useState(initialMenu);\nconst addMenuItem = (item: MenuItem) => {\n  setMenu(previous => [...previous, item]);\n};\n// Also valid for one update based on this render's menu:\n// setMenu([...menu, item]);\n// Equivalent functional form:\n// setMenu(previous => { return [...previous, item]; }); Both a direct array replacement and a functional update are valid. Lecture 5a slide 10 explicitly teaches both forms. The starter fails because it uses a malformed block/spread expression instead of returning an array. Square brackets construct the array; an expression body returns it automatically. Spreading an array into another array copies element references; it does not deep-copy nested objects. That is enough for appending a new item, provided old objects are not mutated. The typed initialMenu provides information from which useState infers MenuItem[]. Add Soup after Tea; the next array contains both in order. Keep a reference to the old array in a standalone equivalent; its length remains 1 and the next array is a different reference. Queue two functional appends in the same event; both items remain. Prepend the new item, then explain the difference between [item, ...previous] and [...previous, item]."}, {"title": "Update one object and remove another", "url": "exercises.html#e05", "category": "Exercise", "terms": "e05 Update one object and remove another Essential map filter object spread immutability Write two handlers inside a component that stores Task[] in state. toggleTask(id) changes only the matching task’s done value. removeTask(id) deletes only that task. The IDs are unique. type Task = { id: string; title: string; done: boolean };\nconst [tasks, setTasks] = useState<Task[]>([\n  { id: \"t1\", title: \"Read\", done: false },\n  { id: \"t2\", title: \"Practice\", done: true },\n]);\n// Write toggleTask and removeTask here. Return new arrays. Copy the changed object instead of mutating it. Keep IDs stable. Do nothing harmful when an ID is absent. map preserves a one-for-one relationship; filter selects which elements remain. For the matching task return { ...task, done: !task.done }. The filter callback should return true for tasks to keep. // Component-body fragment; useState is imported and tasks exist.\nfunction toggleTask(id: string) {\n  setTasks(previous => previous.map(task =>\n    task.id === id ? { ...task, done: !task.done } : task\n  ));\n}\nfunction removeTask(id: string) {\n  setTasks(previous => previous.filter(task => task.id !== id));\n} An immutable edit copies each level that changes: the array and the matching task object. Unchanged task objects may retain their references because their values are unchanged. [...previous] followed by next[0].done = true would still mutate the shared first object. filter keeps elements whose predicate is true. To remove t1, keep tasks with task.id !== \"t1\". map transforms elements; it does not remove them just because a callback returns undefined. Toggle t1: t1 becomes true and t2 remains true. Toggle t1 again: it returns to false. Remove t2: only t1 remains. Removing an unknown ID leaves the displayed data unchanged. Save the old t1 object in a standalone test and confirm its done field did not change. Insert a task at index 1 with slice, then replace an item at that index without using map."}, {"title": "Connect a controlled input", "url": "exercises.html#e06", "category": "Exercise", "terms": "e06 Connect a controlled input Essential TextInput controlled state callbacks Create a complete screen that displays a name as it is typed and clears it with a button. The button is disabled when the input is empty. Explain why onChangeText receives a string rather than a browser event. // In a component:\n// <TextInput value={name} onChangeText={/* ? */} /> Keep value and onChangeText connected to the same state. Render text inside Text. Do not call the setter while rendering. Initialize name with useState(\"\"). Pass setName directly because its accepted string value fits this callback. For Clear, pass () => setName(\"\") rather than setName(\"\"). // Complete App.tsx.\nimport { useState } from 'react';\nimport { Button, Text, TextInput, View } from 'react-native';\nexport default function App() {\n  const [name, setName] = useState('');\n  return (\n    <View style={{ padding: 40 }}>\n      <TextInput accessibilityLabel=\"Your name\" value={name}\n        onChangeText={setName}\n        style={{ borderWidth: 1, padding: 12 }} />\n      <Text>Hello, {name || 'friend'}.<\/Text>\n      <Button title=\"Clear\" disabled={name.length === 0}\n        onPress={() => setName('')} />\n    <\/View>\n  );\n} The displayed input value comes from React state. Typing invokes onChangeText with the new string; setName schedules a render; the next value prop reflects that string. This complete loop makes the input controlled. React Native TextInput has onChangeText for direct text values. A browser input often uses an event and event.target.value; copying that web pattern into onChangeText would be incorrect. A value prop without a corresponding update can make the input appear stuck. Typing Alex changes both the input and greeting. Clear empties the field, changes the greeting to friend, and disables itself. Typing a space is allowed by this exercise; explain how trim() would change validation. Add a character counter derived from name.length without introducing another state variable."}, {"title": "Send an action from child to parent", "url": "exercises.html#e07", "category": "Exercise", "terms": "e07 Send an action from child to parent Essential callback props lifting state function types Complete a parent and child pair. The parent owns an array of names. The child owns only the draft text. Pressing Add in the child should ask the parent to append the trimmed name. The array must remain in the parent. type ComposerProps = { onAdd: /* write the function type */ };\nfunction Composer({ onAdd }: ComposerProps) {\n  // Own draft text; call onAdd only on submission.\n}\nexport default function App() {\n  // Own names and pass an add handler to Composer.\n} Type onAdd as a function that receives one string and returns no useful value. Reject blank or whitespace-only submissions. Clear the child draft after a successful submission. Use a functional array update in the parent. The type is (name: string) => void. That describes the callback; it does not execute it. The parent passes onAdd={addName}. The child later calls onAdd(cleanName) in a handler. Props travel down; an event invokes a function supplied from above. The child does not directly write the parent’s state. // Complete App.tsx. The names below are append-only; a single Text displays them.\nimport { useState } from 'react';\nimport { Button, Text, TextInput, View } from 'react-native';\ntype ComposerProps = { onAdd: (name: string) => void };\nfunction Composer({ onAdd }: ComposerProps) {\n  const [draft, setDraft] = useState('');\n  function submit() {\n    const name = draft.trim();\n    if (!name) return;\n    onAdd(name);\n    setDraft('');\n  }\n  return (\n    <View>\n      <TextInput accessibilityLabel=\"New name\" value={draft}\n        onChangeText={setDraft} style={{ borderWidth: 1, padding: 12 }} />\n      <Button title=\"Add\" onPress={submit} disabled={!draft.trim()} />\n    <\/View>\n  );\n}\nexport default function App() {\n  const [names, setNames] = useState<string[]>([]);\n  function addName(name: string) {\n    setNames(previous => [...previous, name]);\n  }\n  return (\n    <View style={{ padding: 40 }}>\n      <Composer onAdd={addName} />\n      <Text>{names.length ? names.join(', ') : 'No names yet'}<\/Text>\n    <\/View>\n  );\n} There are two pieces of state with different owners. The draft is used only inside the form, so it stays there. The submitted names are needed by the parent display, so they live in App. If two siblings later need the same draft, move it to their nearest common ancestor. onAdd is a prop containing a function value. Calling it reports an action to the parent’s handler. This does not reverse the direction of props: the parent still supplies both data and callbacks downward, and owns the state update. Type two names and submit each. Both appear in order. Submitting spaces adds nothing. Explain the path from the press, through submit and onAdd, to setNames and the next render. Change the callback to accept { name, popular } instead of a string and adjust both its type and the object passed by the child."}, {"title": "Place types where inference needs help", "url": "exercises.html#e08", "category": "Exercise", "terms": "e08 Place types where inference needs help Essential TypeScript inference union types props Complete this standalone TypeScript and React-state typing drill. Explain which annotations are needed for the intended future values, and which can be inferred. Do not add any or assertions to silence errors. type MenuItem = { id: string; name: string; popular: boolean };\n// Inside a component with useState imported:\nconst [title, setTitle] = useState('Menu');\nconst [items, setItems] = useState([]);\nconst [selected, setSelected] = useState(null);\n// Outside the component:\nconst summarize = (item) => item.name;\n// Define a props type for one item and an onChoose callback. Allow items to hold MenuItem objects. Allow selected to hold a MenuItem or null. Type summarize’s parameter. Define onChoose as receiving a MenuItem. An empty array provides no useful element examples. Under common strict React TypeScript settings it can infer never[]. null alone does not describe a future MenuItem; use a union. Return string from summarize can be inferred from the typed parameter. // State lines go inside a component; useState must be imported.\nconst [title, setTitle] = useState('Menu'); // string is inferred\nconst [items, setItems] = useState<MenuItem[]>([]);\nconst [selected, setSelected] = useState<MenuItem | null>(null);\n\n// Type declarations and this function can live outside the component.\nconst summarize = (item: MenuItem) => item.name;\ntype CardProps = {\n  item: MenuItem;\n  onChoose: (item: MenuItem) => void;\n}; Inference is strongest when a value or surrounding context gives TypeScript useful evidence. A typed initial array, such as const initial: MenuItem[] = [], lets useState(initial) infer the same type. For an empty literal or null, an explicit type expresses the later states you intend. TypeScript checks code before execution; types do not validate unknown network responses at runtime. The compiler can catch setTitle(42), but a type annotation alone cannot guarantee that downloaded JSON has the promised shape. setItems([{ id: \"a\", name: \"Tea\", popular: true }]) type-checks; an item missing popular does not. setSelected(null) and setSelected(aMenuItem) are permitted. Before reading selected.name, use selected !== null or optional chaining; explain the possible absent case. Define a union status type \"idle\" | \"loading\" | \"ready\" | \"error\" and explain what misspellings it catches."}, {"title": "Build a nested layout from a verbal description", "url": "exercises.html#e09", "category": "Exercise", "terms": "e09 Build a nested layout from a verbal description Reinforcement Flexbox StyleSheet box model core components Build a profile card. Its outer container is a column. The top row places a 64-unit avatar placeholder beside a text column. A bottom row spreads two buttons apart. Explain the main and cross axes of each row. // Create a complete App.tsx using View, Text, Button, and StyleSheet.\n// Use a colored View as the avatar so this exercise works offline. Use nested containers instead of absolute positioning. Apply padding inside the card and margin outside it. Let the text column use the remaining row width. Use styles defined with StyleSheet.create. React Native flexDirection defaults to column. Give the two horizontal containers flexDirection: \"row\". In a row, justifyContent controls horizontal distribution and alignItems controls vertical alignment. Use flex: 1 on the text column; the parent card must have available width. // Complete App.tsx.\nimport { Button, StyleSheet, Text, View } from 'react-native';\nexport default function App() {\n  return (\n    <View style={styles.screen}>\n      <View style={styles.card}>\n        <View style={styles.top}>\n          <View style={styles.avatar} />\n          <View style={styles.description}>\n            <Text style={styles.name}>Jordan<\/Text>\n            <Text>First-year student learning mobile development.<\/Text>\n          <\/View>\n        <\/View>\n        <View style={styles.actions}>\n          <Button title=\"Follow\" onPress={() => {}} />\n          <Button title=\"Message\" onPress={() => {}} />\n        <\/View>\n      <\/View>\n    <\/View>\n  );\n}\nconst styles = StyleSheet.create({\n  screen: { flex: 1, paddingTop: 48, backgroundColor: '#E8EDFF' },\n  card: { margin: 16, padding: 16, borderWidth: 1,\n    borderColor: '#6574A0', borderRadius: 16, backgroundColor: 'white' },\n  top: { flexDirection: 'row', alignItems: 'center' },\n  avatar: { width: 64, height: 64, borderRadius: 32, backgroundColor: '#815AE8' },\n  description: { flex: 1, marginLeft: 16 },\n  name: { fontSize: 20, fontWeight: '700' },\n  actions: { flexDirection: 'row', justifyContent: 'space-between', marginTop: 20 },\n}); Each container controls only its direct children. The card stacks the top row and action row vertically. The top row controls the avatar and text column. The text column then stacks its own Text children. This tree makes the two-dimensional layout easier to reason about. padding creates space between the card border and its content. margin creates space outside the card. A numeric size uses React Native logical layout units; it is not a CSS string such as \"64px\". The placeholder buttons intentionally have no behavior in this layout-only exercise. Narrow the window: text wraps and remains beside the avatar. Change top.flexDirection to column and predict the positions before running. Set alignItems to flex-start and observe only the top row’s cross-axis alignment change. Replace the placeholder with Image using a remote URI and explicit dimensions; explain why an image may need width and height."}, {"title": "Rebuild the complete campus menu", "url": "exercises.html#e10", "category": "Exercise", "terms": "e10 Rebuild the complete campus menu Integration state map callbacks TextInput TypeScript immutable arrays Build an original campus menu app from a blank App.tsx. App owns MenuItem[]. Composer owns name and popular draft state and receives an onAdd callback. ItemCard receives one item and callbacks. Begin with two items, add new ones, toggle popularity, and remove items. Build adding first; toggling and removal are extensions if time remains. A complete reference file is provided at practice/MenuApp.tsx. type MenuDraft = { name: string; popular: boolean };\ntype MenuItem = MenuDraft & { id: string };\n// Sketch App -> Composer and App -> ItemCard before coding.\n// Start with static cards, then add state, then wire callbacks. Use one parent-owned menu array and stable IDs. Render cards with map and keys. Add a trimmed nonblank name through the child callback. Use functional immutable state updates. Show an empty state after removing every item. Explain each callback type aloud. First render two hard-coded cards. Then replace duplicate JSX with menu.map. Give Composer the type { onAdd: (draft: MenuDraft) => void }. A button calls onAdd({ name: cleanName, popular }). The parent gives the draft an ID, then calls setMenu(previous => [...previous, item]). Generate the ID outside the updater so the updater remains pure. // Complete App.tsx for a standard Expo React Native TypeScript project or Snack.\n// Original practice solution. Rebuild from the requirements before reading it.\nimport { useState } from 'react';\nimport {\n  Button, Pressable, ScrollView, StyleSheet,\n  Switch, Text, TextInput, View,\n} from 'react-native';\n\ntype MenuDraft = { name: string; popular: boolean };\nexport type MenuItem = MenuDraft & { id: string };\nconst initialMenu: MenuItem[] = [\n  { id: '1', name: 'Rice bowl', popular: true },\n  { id: '2', name: 'Fruit cup', popular: false },\n];\n\ntype ComposerProps = { onAdd: (draft: MenuDraft) => void };\nfunction Composer({ onAdd }: ComposerProps) {\n  const [name, setName] = useState('');\n  const [popular, setPopular] = useState(false);\n  const cleanName = name.trim();\n  function submit() {\n    if (cleanName.length === 0) return;\n    onAdd({ name: cleanName, popular });\n    setName('');\n    setPopular(false);\n  }\n  return (\n    <View style={styles.composer}>\n      <TextInput\n        accessibilityLabel=\"New menu item name\"\n        placeholder=\"New menu item\"\n        value={name}\n        onChangeText={setName}\n        style={styles.input}\n      />\n      <View style={styles.row}>\n        <Text>Popular<\/Text>\n        <Switch\n          accessibilityLabel=\"Mark new item popular\"\n          value={popular}\n          onValueChange={setPopular}\n        />\n      <\/View>\n      <Button title=\"Add item\" disabled={!cleanName} onPress={submit} />\n    <\/View>\n  );\n}\n\ntype CardProps = {\n  item: MenuItem;\n  onToggle: (id: string) => void;\n  onRemove: (id: string) => void;\n};\nfunction ItemCard({ item, onToggle, onRemove }: CardProps) {\n  return (\n    <View style={styles.card}>\n      <Text style={styles.itemName}>{item.name}<\/Text>\n      <Text>{item.popular ? 'Popular choice' : 'Regular choice'}<\/Text>\n      <View style={styles.actions}>\n        <Pressable\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Toggle popularity of ${item.name}`}\n          onPress={() => onToggle(item.id)}\n          style={styles.action}\n        >\n          <Text>Toggle popular<\/Text>\n        <\/Pressable>\n        <Pressable\n          accessibilityRole=\"button\"\n          accessibilityLabel={`Remove ${item.name}`}\n          onPress={() => onRemove(item.id)}\n          style={styles.action}\n        >\n          <Text>Remove<\/Text>\n        <\/Pressable>\n      <\/View>\n    <\/View>\n  );\n}\n\nexport default function App() {\n  const [menu, setMenu] = useState(initialMenu);\n  const [nextId, setNextId] = useState(3);\n  function addMenuItem(draft: MenuDraft) {\n    const item: MenuItem = { ...draft, id: String(nextId) };\n    setNextId(previous => previous + 1);\n    setMenu(previous => [...previous, item]);\n  }\n  function togglePopular(id: string) {\n    setMenu(previous => previous.map(item =>\n      item.id === id ? { ...item, popular: !item.popular } : item\n    ));\n  }\n  function removeItem(id: string) {\n    setMenu(previous => previous.filter(item => item.id !== id));\n  }\n  return (\n    <View style={styles.screen}>\n      <Text style={styles.title}>Campus menu<\/Text>\n      <Text>{menu.length} items<\/Text>\n      <Composer onAdd={addMenuItem} />\n      <ScrollView contentContainerStyle={styles.list}>\n        {menu.length === 0 ? (\n          <Text>No items yet. Add your first one.<\/Text>\n        ) : null}\n        {menu.map(item => (\n          <ItemCard\n            key={item.id}\n            item={item}\n            onToggle={togglePopular}\n            onRemove={removeItem}\n          />\n        ))}\n      <\/ScrollView>\n    <\/View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  screen: {\n    flex: 1, paddingTop: 48, paddingHorizontal: 20,\n    paddingBottom: 20, backgroundColor: '#F6F8FF',\n  },\n  title: { fontSize: 28, fontWeight: '700', marginBottom: 6 },\n  composer: { paddingVertical: 16 },\n  input: {\n    borderWidth: 1, borderColor: '#556080', borderRadius: 8,\n    padding: 12, backgroundColor: '#FFFFFF',\n  },\n  row: {\n    flexDirection: 'row', alignItems: 'center',\n    justifyContent: 'space-between', marginVertical: 8,\n  },\n  list: { paddingBottom: 24 },\n  card: {\n    padding: 16, marginBottom: 12, borderRadius: 12,\n    backgroundColor: '#FFFFFF', borderWidth: 1, borderColor: '#CBD5E1',\n  },\n  itemName: { fontSize: 18, fontWeight: '600', marginBottom: 4 },\n  actions: { flexDirection: 'row', flexWrap: 'wrap', marginTop: 8 },\n  action: {\n    minHeight: 44, justifyContent: 'center', paddingHorizontal: 12,\n    marginRight: 8, marginBottom: 4, borderRadius: 8,\n    backgroundColor: '#DDE8FF',\n  },\n});\n This exercise combines rendering, state, callbacks, and TypeScript. It separates the form’s temporary input from the parent’s submitted data, and makes the callback contract visible in TypeScript. The parent is the single source of truth for displayed menu items. The ID counter is state for this small in-memory practice app and each user submit creates one item. IDs are assigned once at creation rather than during rendering. A real persistent app would need an ID strategy appropriate to storage and multiple clients. Add, toggle, and remove each return a new array. Toggle additionally creates a new object only for the changed item. The displayed count is derived from menu.length, so no second count state can drift out of sync. The screen padding is intentionally simple; production safe-area and keyboard behavior are separate concerns. Add \"  Noodles  \": exactly one Noodles card appears and the input clears. Submit a blank field: nothing is added. Add two items with the same name: their distinct IDs allow independent toggling and removal. Toggle one item twice: other items do not change. Remove all items: the count becomes zero and the empty message appears. Add an item after clearing the list: it appears normally with a new ID. Without opening the reference, rebuild the same data flow for a reading list with title and finished fields."}, {"title": "Fix imports and component props", "url": "exercises.html#e11", "category": "Exercise", "terms": "e11 Fix imports and component props Reinforcement imports exports components props You are given two local files. Fix the imports and the prop usage. Explain why default and named imports have different syntax. This drill is about modules; do not run the two files as one pasted file. // Card.tsx\nexport type CardProps = { title: string };\nexport default function Card({ title }: CardProps) { /* valid JSX omitted */ }\nexport const accent = '#5B3FD4';\n\n// App.tsx\nimport { Card } from './Card';\nimport accent from './Card';\n// <Card name=\"Study\" /> Import the default component without braces. Import accent by its exported name. Pass the prop that CardProps declares. A default export can be given a local name by the importer. A named export uses braces; aliases use as. CardProps expects title, not name. // App.tsx import and JSX fragments; Card.tsx is the separate module.\nimport Card, { accent } from './Card';\nimport type { CardProps } from './Card';\n// Within JSX:\n// <Card title=\"Study\" />\n// accent is available for a style, e.g. { color: accent }.\n\n// Equally valid import with local aliases:\n// import StudyCard, { accent as brandColor } from './Card'; A module has at most one default export and may have many named exports. The default import does not use braces. Named imports match exported names, unless an explicit alias changes the local name. import type makes it clear that CardProps is used only by TypeScript. Props are one object parameter. Destructuring { title } extracts the title property; it does not mean the component receives an arbitrary positional string. JSX attribute names must agree with the declared props contract. The corrected import resolves the default Card and named accent. TypeScript reports an error for <Card name=\"Study\" /> because title is missing and name is not declared. Rename the default import to StudyCard and update the JSX; it still refers to the same component. Split the integrated menu app into Composer.tsx, ItemCard.tsx, types.ts, and App.tsx."}, {"title": "Debug rendering and event mistakes", "url": "exercises.html#e12", "category": "Exercise", "terms": "e12 Debug rendering and event mistakes Essential debugging events conditional rendering keys Repair the fragment and explain the order of events. Assume imports, count state, and the list are already declared. Do not fix a render-time update with useEffect; fix when the handler runs. return (\n  <View>\n    <Button title=\"Add\" onPress={setCount(count + 1)} />\n    {count && <Text>There are items<\/Text>}\n    {items.map(item => <Text key={Math.random()}>{item.name}<\/Text>)}\n  <\/View>\n); Update only on a button press. Show the message only when count is greater than zero. Use a stable ID for each row. A JSX prop expression runs while rendering. setCount(...) calls the setter immediately. Logical && returns one of its operands; 0 && something evaluates to 0. Assume each item has a stable id assigned when created. // Component JSX fragment; count, setCount, and items already exist.\nreturn (\n  <View>\n    <Button title=\"Add\" onPress={() => setCount(c => c + 1)} />\n    {count > 0 ? <Text>There are items<\/Text> : null}\n    {items.map(item => <Text key={item.id}>{item.name}<\/Text>)}\n  <\/View>\n); onPress expects a function that React Native can call later. Passing the result of setCount invokes the update during render and supplies no useful handler. Wrapping the call defers it until the press. A named handler passed as onPress={handleAdd} works too. A numeric left side of && can produce the number zero rather than an element or nothing. React Native requires text to be inside Text, so prefer an explicit Boolean condition. Random keys change on every render and can remount rows, losing local state and focus. Initial render performs no update. Pressing Add changes count once. At zero, no raw 0 is inserted as a View child by the condition. A re-render keeps the same key for each unchanged item. Explain the difference between onPress={handleAdd}, onPress={() => handleAdd()}, and onPress={handleAdd()}."}, {"title": "Run one interval and clean it up", "url": "exercises.html#e13", "category": "Exercise", "terms": "e13 Run one interval and clean it up Lecture breadth useEffect timers cleanup hooks Create a seconds counter that runs while running is true and pauses when false. This covers Lecture 5a. Use an effect to manage one interval and clean it up. Predict what happens after repeatedly pausing and restarting. // Component-body starting point:\nconst [seconds, setSeconds] = useState(0);\nconst [running, setRunning] = useState(false);\n// Add an effect and Start/Pause button. Call hooks unconditionally at the top level. Create the interval only while running. Clear the interval when running changes or the component unmounts. Use a functional setter inside the interval. The effect depends on running, because that value determines whether an interval exists. The cleanup must return a function: return () => clearInterval(id). The interval callback uses setSeconds(s => s + 1), so it does not need to capture seconds. // Complete App.tsx.\nimport { useEffect, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\nexport default function App() {\n  const [seconds, setSeconds] = useState(0);\n  const [running, setRunning] = useState(false);\n  useEffect(() => {\n    if (!running) return;\n    const id = setInterval(() => setSeconds(s => s + 1), 1000);\n    return () => clearInterval(id);\n  }, [running]);\n  return (\n    <View style={{ padding: 40 }}>\n      <Text>{seconds} seconds<\/Text>\n      <Button title={running ? 'Pause' : 'Start'}\n        onPress={() => setRunning(value => !value)} />\n      <Button title=\"Reset\" onPress={() => setSeconds(0)} />\n    <\/View>\n  );\n} An effect synchronizes React with a system outside rendering: here a timer. When running changes, React cleans up the previous effect before running the next setup. When the component is removed, it cleans up again. Without cleanup, repeated starts can leave multiple intervals running. The updater receives fresh pending state, avoiding a callback that keeps incrementing an old captured seconds value. Effects with [] are mount-oriented, but development Strict Mode may perform an extra setup-cleanup-setup cycle to detect missing cleanup. Timers are not exact clocks; this is a teaching counter, not a precise stopwatch. Start: the number increases approximately once each second. Pause: the number stops changing. Start again: it does not accelerate. Reset while running: the display becomes zero and continues on the existing interval. Remove the component: no interval from it remains active. Build a countdown that stops at zero. Explain why calling setInterval in the render body would create repeated timers."}, {"title": "Predict and chain Promises", "url": "exercises.html#e14", "category": "Exercise", "terms": "e14 Predict and chain Promises Lecture breadth Promises then asynchronous ordering Use the supplied delay function in a standalone TypeScript environment. Predict the log order, then repair the chain so the second then receives the doubled number. This models Lecture 5b without needing network access. function delayValue(value: number, ms: number): Promise<number> {\n  return new Promise(resolve => setTimeout(() => resolve(value), ms));\n}\nconsole.log('A');\ndelayValue(3, 20)\n  .then(value => { value * 2; })\n  .then(value => console.log('C', value));\nconsole.log('B'); Predict the synchronous log order before running. Return the doubled value from the first then. Explain that the Promise represents an eventual result. Starting an asynchronous operation does not pause the later console.log(\"B\"). A then callback’s returned value becomes the fulfillment value of the next Promise in the chain. Use .then(value => value * 2) or a block with return. // Standalone TypeScript; timer scheduling affects delay, not this log order.\nfunction delayValue(value: number, ms: number): Promise<number> {\n  return new Promise(resolve => setTimeout(() => resolve(value), ms));\n}\nconsole.log('A');\ndelayValue(3, 20)\n  .then(value => value * 2)\n  .then(value => console.log('C', value))\n  .catch(error => console.error('Failed:', error));\nconsole.log('B');\n// Logs A, then B, then C 6 after the timer resolves. The first two logs happen in the current synchronous work. The timer later resolves the Promise with 3, allowing the then callbacks to run. then returns another Promise, so a chain represents a sequence of asynchronous and synchronous transformations. The original block callback did not return its calculation. Its next then received undefined. This is the same missing-return idea as the broken map callback, applied to a different API. catch is an error-handling extension to the deck’s basic then examples; it handles a rejection or an error thrown in the preceding chain. The output order is A, B, C 6. Restore the original missing return: C receives undefined. Throw new Error(\"practice\") in the first then; the catch runs and the success log is skipped. Write a delayText function returning Promise<string>, and transform the fulfilled text to uppercase."}, {"title": "Insert and replace with slice", "url": "exercises.html#e15", "category": "Exercise", "terms": "e15 Insert and replace with slice Reinforcement array spread slice immutable arrays This standalone TypeScript drill follows Lecture 4b slide 7. Starting with [\"A\", \"B\", \"C\", \"D\"], insert X at index 2, replace index 2 with X, and remove index 2. Each operation must start from the original array, not the previous answer. const letters = ['A', 'B', 'C', 'D'];\nconst inserted = /* ? */;\nconst replaced = /* ? */;\nconst removed = /* ? */; Leave letters unchanged. Explain slice’s excluded end index. Use a new array for each result. letters.slice(0, 2) gives A and B. Insertion resumes at index 2; replacement and removal resume at index 3. Spread the two slices around the inserted value. // Standalone TypeScript.\nconst letters = ['A', 'B', 'C', 'D'];\nconst inserted = [...letters.slice(0, 2), 'X', ...letters.slice(2)];\nconst replaced = [...letters.slice(0, 2), 'X', ...letters.slice(3)];\nconst removed = [...letters.slice(0, 2), ...letters.slice(3)];\n// inserted: ['A', 'B', 'X', 'C', 'D']\n// replaced: ['A', 'B', 'X', 'D']\n// removed: ['A', 'B', 'D']\n// letters: ['A', 'B', 'C', 'D'] slice returns a shallow copy of the requested portion without changing the source. Its end index is exclusive. Insertion keeps the original element at index 2; replacement and removal deliberately skip it by continuing from index 3. The different bracket roles matter: array literals use square brackets, function calls use parentheses, and object literals use braces. Naming the role of each delimiter is a faster debugging method than adding punctuation until the error disappears. Check the three exact outputs above and confirm the original still has length 4. Insert at index 0 and at letters.length; predict both outputs. Change the index to 1 and compute the three results on paper first. Use slice inside setTasks(previous => ...) to insert a task at a chosen position."}, {"title": "Explain a cross-platform implementation choice", "url": "exercises.html#e16", "category": "Exercise", "terms": "e16 Explain a cross-platform implementation choice Lecture breadth cross-platform Expo React Native core components This is a design-and-code interview drill. A campus club wants one small app for iOS and Android with text, images, and a sign-up form. Explain what React Native and Expo each provide, then translate the web fragment below to React Native. No networking is required. // Web JSX to translate:\n// <div className=\"card\"><p>Join the club<\/p><input /><\/div> Use View, Text, and TextInput. State one shared-code benefit and one platform-specific testing need. Do not claim React Native is a web page inside a browser. Explain that Expo Go supports a fixed set of native capabilities. Core React Native components map to platform-native views on iOS and Android. React provides the component/state model; React Native provides native UI components; Expo provides a framework, libraries, and development tools. Use style objects rather than className in a standard React Native setup. // Component JSX fragment. name and setName are useState values.\n<View style={{ padding: 16, borderWidth: 1 }}>\n  <Text>Join the club<\/Text>\n  <TextInput accessibilityLabel=\"Your name\"\n    value={name} onChangeText={setName}\n    style={{ borderWidth: 1, padding: 12 }} />\n<\/View> Shared TypeScript and React components can reduce duplicated application logic across iOS and Android. React Native renders platform-native views rather than requiring a WebView for the entire interface. Behavior still differs across devices, so test keyboard handling, text size, safe areas, permissions, and touch interactions on the target platforms. Expo simplifies the React Native development workflow and offers libraries and services. Expo Go is convenient for supported APIs, but a custom native dependency can require a development build. A browser preview is useful for iteration, but it does not prove that an app behaves correctly on iOS and Android. Explain every translated component and how its props differ from the web element. Identify a keyboard or layout behavior to test separately on each platform. Distinguish a browser web app, an installable PWA, and a React Native app in two sentences each. Explain when a simple browser-based app might be sufficient, without assuming one approach is always better."}, {"title": "What do n => n * 2 and n => { n * 2; } return for n = 5?", "url": "interviews.html#q01", "category": "Question", "terms": "q01 Arrow functions What do n => n * 2 and n => { n * 2; } return for n = 5? Name the two forms of function body. The expression body returns 10. The block body computes 10 but returns undefined because it has no return statement. Adding return inside the block makes the functions equivalent for this input. Parentheses around a multiline expression improve grouping but do not replace a required return in a block. Rewrite both valid forms with the parameter type number."}, {"title": "Why does () => ({ popular: true }) return an object?", "url": "interviews.html#q02", "category": "Question", "terms": "q02 Objects Why does () => ({ popular: true }) return an object? The parentheses distinguish an expression from a statement block. After =>, a bare opening brace starts the function body. Wrapping { popular: true } in parentheses makes it an object expression, which the arrow returns implicitly. An equivalent block form is () => { return { popular: true }; }. Write a function that receives name and returns { name, popular: false }."}, {"title": "Given [2, 5, 8].map(n => n + 1), what is returned and what happens to the original?", "url": "interviews.html#q03", "category": "Question", "terms": "q03 map Given [2, 5, 8].map(n => n + 1), what is returned and what happens to the original? Follow one input element at a time. The result is a new array [3, 6, 9]. The original remains [2, 5, 8] because this callback only computes values. map itself does not require mutation, but a callback can still mutate an object if written carelessly. For a normal dense array, each input element contributes one returned value. What does map produce if its callback returns nothing?"}, {"title": "What is the difference between the braces in {items.map(...)} and the braces in item => { return ...; }?", "url": "interviews.html#q04", "category": "Question", "terms": "q04 JSX What is the difference between the braces in {items.map(...)} and the braces in item => { return ...; }? The same character has different jobs in different positions. The JSX braces enter a JavaScript expression within markup. The arrow braces create a function statement block, where return is needed to supply a value. An object literal also uses braces. Debugging starts by identifying each brace’s role rather than treating all braces as interchangeable. Name the roles of every delimiter in setItems(prev => [...prev, item])."}, {"title": "Why can useState(initialItems) infer Item[], while useState([]) may need an explicit type?", "url": "interviews.html#q05", "category": "Question", "terms": "q05 TypeScript inference Why can useState(initialItems) infer Item[], while useState([]) may need an explicit type? Ask what information is available in each initial value. If initialItems is declared Item[], useState receives that evidence and infers the state type. An empty literal gives no element examples; in common strict React TypeScript settings useState([]) can infer never[]. useState<Item[]>([]) states the intended element type. Inference is useful, but it cannot guess all future values. What annotation would you use for a selected item that initially has no value?"}, {"title": "Does type User = { name: string } guarantee a downloaded JSON object has a name?", "url": "interviews.html#q06", "category": "Question", "terms": "q06 TypeScript boundaries Does type User = { name: string } guarantee a downloaded JSON object has a name? Separate static checking from runtime execution. No. TypeScript’s type annotations are removed before execution and do not inspect downloaded values. A type assertion merely tells the compiler what to assume. Unknown external data needs runtime checks or validation before the app trusts its shape. This is a conceptual extension beyond the supplied Promise examples. What simple check would you perform before reading an unknown value as a name?"}, {"title": "Why is let count = 0 inside a component insufficient for an interactive counter?", "url": "interviews.html#q07", "category": "Question", "terms": "q07 State Why is let count = 0 inside a component insufficient for an interactive counter? Consider both updating the screen and remembering a value. Changing an ordinary local variable does not ask React to render again. Also, the component function runs again on a later render and recreates the local initialization. useState retains a value across renders and provides a setter that schedules an update. A module-level variable survives calls but still does not notify React, and may be unintentionally shared. What happens to a local variable if a parent causes the component to render again?"}, {"title": "Starting from count = 0, a handler calls setCount(count + 1) twice. What is the next count?", "url": "interviews.html#q08", "category": "Question", "terms": "q08 State snapshots Starting from count = 0, a handler calls setCount(count + 1) twice. What is the next count? Both expressions read the same render’s count. The next count is 1. Each call asks for the value 1 computed from the captured zero. Two calls to setCount(c => c + 1) instead compose to 2 because each updater receives the pending result of the previous update. The current handler still reads its original snapshot after scheduling updates. Predict setCount(5); setCount(c => c + 1) from an initial count of zero."}, {"title": "Is setMenu(previous => [...previous, item]) valid? What is wrong with setMenu(previous => { ...previous, item })?", "url": "interviews.html#q09", "category": "Question", "terms": "q09 Setter forms Is setMenu(previous => [...previous, item]) valid? What is wrong with setMenu(previous => { ...previous, item })? Keep the updater-function idea and inspect the returned value. It is valid and is useful when the next array depends on the previous array. A React setter accepts a next value or a pure updater function. The attempted code used braces and spread in an invalid block rather than returning a new array. Square brackets form the array; an expression body returns it automatically. Show the equivalent block-body updater and the direct replacement form."}, {"title": "Is const next = [...items]; next[0].popular = true an immutable update?", "url": "interviews.html#q10", "category": "Question", "terms": "q10 Immutable updates Is const next = [...items]; next[0].popular = true an immutable update? What exactly was copied? The array was copied, but its objects are still shared. Changing next[0].popular mutates the same object referenced by items[0]. For a change to one item, use map and return { ...item, popular: true } for the matching item. Copy each level whose contents change. Unchanged objects may retain their references. Why is [...items, newItem] sufficient when you are only appending?"}, {"title": "Explain onPress={save}, onPress={() => save()}, and onPress={save()}.", "url": "interviews.html#q11", "category": "Question", "terms": "q11 Callbacks Explain onPress={save}, onPress={() => save()}, and onPress={save()}. Distinguish a function value from the result of a call. The first passes save itself. The second passes a new function that calls save when pressed. The third calls save during rendering and supplies its return value as the prop, which is usually wrong. A wrapper is especially useful when passing a chosen argument, such as () => removeItem(item.id). When can onChangeText={setName} be used directly?"}, {"title": "Two sibling components must display and change the same selected item. Where should the state live?", "url": "interviews.html#q12", "category": "Question", "terms": "q12 Lifting state Two sibling components must display and change the same selected item. Where should the state live? Locate their nearest common ancestor. Store it in their nearest common ancestor, pass the current selection down as props, and pass callbacks that request changes. This gives one source of truth. Keeping independent copies in each sibling creates a synchronization problem. State can remain local when no other component needs it. Why might a form’s unsent draft stay in the form while submitted items live in the parent?"}, {"title": "Explain the type onAdd: (item: MenuItem) => void.", "url": "interviews.html#q13", "category": "Question", "terms": "q13 Function props Explain the type onAdd: (item: MenuItem) => void. Read it as a contract for a value that is a function. onAdd is a property containing a function. The function accepts one MenuItem argument. Its caller does not use a returned result, represented by void. The parent supplies a compatible function; the child can call it with an object that includes all required MenuItem fields. The type declaration does not run the function. How would the type change if the callback accepted only an item ID?"}, {"title": "The TextInput has value={name}, but typing does not update the display. What do you inspect?", "url": "interviews.html#q14", "category": "Question", "terms": "q14 Controlled inputs The TextInput has value={name}, but typing does not update the display. What do you inspect? Trace the input-to-state-to-prop loop. Check onChangeText and confirm it receives the new string and calls the setter for name. Verify the input’s value is not hard-coded or derived from another unchanged state. Also inspect whether an effect or parent update resets it. A controlled input displays its supplied value, so user edits must update the state that supplies that value. Why is event.target.value usually the wrong expression for onChangeText?"}, {"title": "Why can an array index be a poor key for an editable or reorderable list?", "url": "interviews.html#q15", "category": "Question", "terms": "q15 Keys Why can an array index be a poor key for an editable or reorderable list? A key identifies an item across renders, not merely its current position. If items are inserted, deleted, or reordered, the same index can refer to a different item. React may associate row state or focus with the wrong data. Use a stable unique ID stored with each item. Random keys are also poor because they force new identities every render. A key is not automatically passed as a normal child prop. Where should key go when map returns a custom ItemCard?"}, {"title": "In a row container, what do justifyContent and alignItems control? What changes in a column?", "url": "interviews.html#q16", "category": "Question", "terms": "q16 Flexbox In a row container, what do justifyContent and alignItems control? What changes in a column? Start by drawing the main axis. justifyContent distributes children along the main axis. In a row that axis is horizontal; in a column it is vertical. alignItems aligns children across the cross axis, which is perpendicular. React Native defaults to column, unlike the familiar web flex-direction default of row. The parent’s size must allow visible free space for distribution to be obvious. Which container should receive these styles in a nested card layout?"}, {"title": "What is the difference between padding, margin, and borderWidth?", "url": "interviews.html#q17", "category": "Question", "terms": "q17 Box model What is the difference between padding, margin, and borderWidth? Trace from content outward. Padding creates space inside the border between the content and the edge. The border surrounds that padded content. Margin creates space outside the border between neighboring layout boxes. Use padding for a comfortable touchable interior and margin for spacing between cards. React Native style property names use camelCase and most numeric dimensions are logical units. Why does margin not increase the interior of a card’s background?"}, {"title": "When would you use View, Text, Image, TextInput, and ScrollView?", "url": "interviews.html#q18", "category": "Question", "terms": "q18 Core components When would you use View, Text, Image, TextInput, and ScrollView? Match each component to one job. View groups and lays out content. Text displays text and supports nested styled text. Image displays an image from a source and often needs explicit dimensions. TextInput gathers editable text, usually using state. ScrollView makes bounded content scrollable and renders its children together. For very large lists, FlatList is a useful extension because it renders a window of rows. Why should arbitrary text not be placed directly inside View?"}, {"title": "What is wrong with import { Card } from \"./Card\" if Card.tsx exports default function Card()?", "url": "interviews.html#q19", "category": "Question", "terms": "q19 Modules What is wrong with import { Card } from \"./Card\" if Card.tsx exports default function Card()? Braces indicate a named import. The module provides a default export, so use import Card from \"./Card\". The local name could also be MenuCard. Named exports use braces and match the exported name unless explicitly aliased. Type-only exports can be imported with import type. Package imports resolve installed dependencies; relative imports resolve local files. Show a single statement importing a default Card and a named color."}, {"title": "Why should useState not be called inside an if statement?", "url": "interviews.html#q20", "category": "Question", "terms": "q20 Hooks Why should useState not be called inside an if statement? React depends on consistent hook ordering between renders. If the condition changes, the component calls a different sequence of hooks. React can no longer associate each hook position with the same state or effect. Call hooks at the top level of a React function component or custom hook, before conditional returns. Place conditional behavior inside an effect or event handler instead of around the hook call. How would you run an effect only while running is true without conditionally calling useEffect?"}, {"title": "Compare no dependency array, [], and [running] for useEffect.", "url": "interviews.html#q21", "category": "Question", "terms": "q21 Effects Compare no dependency array, [], and [running] for useEffect. Each case still involves setup after a committed render. Without a dependency array the effect runs after each commit of that component. With [], it is tied to mounting rather than changed reactive dependencies. With [running], it runs on mount and after commits where running changes. Cleanup runs before a replacement setup and on unmount. Development Strict Mode may add an extra setup-cleanup cycle, so [] is not a universal promise of exactly one call. Why should every reactive value used by an effect be considered for its dependencies?"}, {"title": "Why does a counter accelerate after the user repeatedly opens and closes a screen?", "url": "interviews.html#q22", "category": "Question", "terms": "q22 Timer cleanup Why does a counter accelerate after the user repeatedly opens and closes a screen? Count how many intervals may still be alive. A likely cause is an interval created without cleanup, so old timers survive while new timers are added. Keep the interval ID inside an effect and return () => clearInterval(id). Also inspect whether a render body starts an interval on every render. A functional state updater avoids a separate stale-count problem, but it does not replace cleanup. What does setSeconds(s => s + 1) solve, and what does clearInterval solve?"}, {"title": "What is logged by console.log(\"A\"); Promise.resolve(2).then(n => console.log(n)); console.log(\"B\")?", "url": "interviews.html#q23", "category": "Question", "terms": "q23 Promises What is logged by console.log(\"A\"); Promise.resolve(2).then(n => console.log(n)); console.log(\"B\")? A fulfilled Promise’s then callback is still scheduled asynchronously. The order is A, B, 2. The synchronous statements finish before the Promise reaction runs. A Promise represents eventual fulfillment or rejection; then attaches a reaction and returns another Promise. Returning a value from a then callback passes it to the next stage; returning another Promise lets the chain wait for that Promise’s result. What happens if a then callback uses braces but forgets return?"}, {"title": "What can be shared in a React Native app, and what must still be tested per platform?", "url": "interviews.html#q24", "category": "Question", "terms": "q24 Cross-platform development What can be shared in a React Native app, and what must still be tested per platform? Separate shared source code from runtime behavior. Components, state logic, TypeScript types, and much styling can be shared. Native controls, keyboard behavior, safe areas, permissions, text scaling, and library support can differ. Expo provides tooling and libraries around React Native; it does not remove the need for device testing. React Native is not simply a browser page packaged as a mobile app. When might a custom native dependency require a development build rather than Expo Go?"}, {"title": "Menu builder rehearsal", "url": "interviews.html#m01", "category": "Mock interview", "terms": "m01 Menu builder rehearsal Original 25-minute practice interview. The evaluator describes a menu screen with a title, a list of cards, and a child form that submits name and popular. These checkpoints and points are a self-study rubric, not an official course rubric. Start with the answer closed and a blank App.tsx. Define a typed MenuItem array and show two initial items. Render a custom ItemCard for each item using map and stable keys. Build a controlled name input and popular control in a Composer child. Pass an onAdd callback from the parent and append immutably. Reject blank input and explain the complete event-to-render path. If time remains, add removal or a popularity toggle. Restate the requirements, draw App with Composer and ItemCard children, and identify who owns each state value. Define the data type and initial state; render the list and inspect the map return. Build the controlled input and child props type; describe the callback argument. Wire the parent callback and immutable append. Test one valid and one blank submission. Test duplicate names and explain why IDs, not names, are keys. Attempt one extension if the core works. Explain direct versus functional setters and identify one limitation or next test. First prompt: What value must the map callback return? Second prompt: Where is the menu state, and which function has access to its setter? Third prompt: A valid append updater returns [...previous, item]. e02 e04 e07 e10 Data and rendering  Uses a meaningful item type, renders data with a returning map callback, and places stable keys correctly. State ownership and controlled input  Keeps the menu in the parent and connects value/onChangeText correctly. Callback contract and event timing  Types and passes the callback, constructs the expected argument, and invokes only on an event. Immutable update  Appends without mutation and explains why an updater function is valid. Reasoning and testing  Narrates the data flow and tests blank input plus a normal add without copying a solution. Record elapsed time to the first successful add and the number of hints used. For each mistake, state the incorrect assumption and the corrected rule. Close every reference and rebuild a reading-list variant later. A correct copied result is not readiness evidence."}, {"title": "Study task list transfer rehearsal", "url": "interviews.html#m02", "category": "Mock interview", "terms": "m02 Study task list transfer rehearsal Original 25-minute transfer interview. Build a study-task screen with title and done fields. The task should feel structurally familiar while changing names and behavior. Attempt it after the menu rehearsal without looking at the menu code. Store Task[] in the parent with id, title, and done. Render each task through a custom row with a visible completion label. Let a child editor add nonblank task titles through a typed callback. Toggle only the selected task through an immutable map update. Display the number of unfinished tasks as a derived value. Use a nested row/column layout with deliberate padding and spacing. Sketch the component tree and list the state values versus derived values. Create the type, seed data, and task rows. Explain stable identity. Wire the child editor and parent add handler with a functional update. Implement toggle by ID, copying the matching object. Derive the unfinished count and test two independent tasks. Explain why a shallow array copy alone would not protect an edited task object. First prompt: What should remain unchanged when only one task changes? Second prompt: A row can receive an onToggle callback and call it with its ID. Third prompt: Use previous.map with a conditional object spread. e05 e07 e09 e10 Independent transfer  Builds a task-oriented solution without copying or merely renaming the menu reference. State and derived values  Uses one tasks state and derives the unfinished count from it. Typed callback flow  Child requests add/toggle through explicit compatible callback props. Immutable object edit  Copies the matching object and preserves other tasks. Layout and debugging  Uses nested containers and tests toggling twice plus blank input. Compare the data flow with the menu app and explain what transferred. Identify any step completed only by recalling punctuation rather than understanding its role. Repeat a smaller version the next day, then add removal without a hint."}, {"title": "State and asynchronous debugging rehearsal", "url": "interviews.html#m03", "category": "Mock interview", "terms": "m03 State and asynchronous debugging rehearsal Original 25-minute breadth interview. Repair small state, timer, and Promise examples and explain their behavior before running them. This practice covers the later supplied lectures and complements the component-building rehearsals. Predict two direct increments versus two updater increments. Repair a render-time handler call and a missing map return. Build a start/pause timer with one effect and cleanup. Predict Promise log order and repair a missing then return. Explain hook placement and why [] is not a guarantee of one setup in development. Predict the queued state examples and explain your reasoning aloud. Repair the missing-return map from e02 and the JSX/event fragment from e12. Describe what triggers each bug. Implement the interval effect from requirements, then test pause/restart behavior. Predict and repair the Promise chain in e14. Explain cleanup, dependencies, and one useful debugging experiment. First prompt: Which values belong to the current render snapshot? Second prompt: What resource must be stopped when this effect is replaced? Third prompt: A block body needs return when it should provide a value. e03 e02 e12 e13 e14 State prediction  Correctly explains snapshot values and queued updater composition. Event and map debugging  Fixes immediate invocation and missing return without unrelated changes. Timer lifecycle  Creates one interval while running and returns cleanup. Promise reasoning  Predicts ordering and passes the returned value through the chain. Explanation and validation  Connects each fix to an observable test and acknowledges dev effect behavior. List each prediction that differed from execution and explain why. Distinguish a stale closure bug from a leaked interval; they need different fixes. If the core menu rehearsal is still weak, return to e01–e08 before adding asynchronous complexity."}, {"title": "Map and return", "url": "labs.html#map", "category": "Visual lab", "terms": "Map and return"}, {"title": "Queued state updates", "url": "labs.html#state", "category": "Visual lab", "terms": "Queued state updates"}, {"title": "Callback flow", "url": "labs.html#callbacks", "category": "Visual lab", "terms": "Callback flow"}, {"title": "Flexbox axes", "url": "labs.html#flex", "category": "Visual lab", "terms": "Flexbox axes"}, {"title": "Effect lifecycle", "url": "labs.html#effects", "category": "Visual lab", "terms": "Effect lifecycle"}, {"title": "Promise ordering", "url": "labs.html#promises", "category": "Visual lab", "terms": "Promise ordering"}, {"title": "Arrow bodies", "url": "cheatsheet.html#cheat-0", "category": "Syntax reference", "terms": "Arrow bodies An expression body returns automatically. A block body needs return to provide a value. const twice = (n: number) => n * 2;\nconst twiceBlock = (n: number) => { return n * 2; };\nconst make = (name: string) => ({ name, popular: false }); A newline or parentheses does not turn a block into an expression. A bare object-looking brace after => begins a block."}, {"title": "Map into elements", "url": "cheatsheet.html#cheat-1", "category": "Syntax reference", "terms": "Map into elements map transforms data into returned values. JSX can render an array of elements. {items.map(item => (\n  <ItemCard key={item.id} item={item} />\n))} Put key on the outermost returned sibling. Missing return produces undefined values; random keys are unstable."}, {"title": "State inference", "url": "cheatsheet.html#cheat-2", "category": "Syntax reference", "terms": "State inference Let useful initial values provide types; annotate empty or nullable state. const [name, setName] = useState('');\nconst [items, setItems] = useState<Item[]>([]);\nconst [selected, setSelected] = useState<Item | null>(null); A typed initial array supports inference. An empty literal or null does not describe all future values."}, {"title": "Two valid setter forms", "url": "cheatsheet.html#cheat-3", "category": "Syntax reference", "terms": "Two valid setter forms Pass the next value, or a pure function that computes the next value from pending state. setCount(0);\nsetCount(previous => previous + 1);\nsetItems(previous => [...previous, item]); Setters accept updater functions. Do not mutate previous or perform side effects inside an updater."}, {"title": "Immutable array operations", "url": "cheatsheet.html#cheat-4", "category": "Syntax reference", "terms": "Immutable array operations Use a new array; copy the changed object when editing an item. setItems(prev => [...prev, item]);\nsetItems(prev => prev.filter(x => x.id !== id));\nsetItems(prev => prev.map(x =>\n  x.id === id ? { ...x, popular: !x.popular } : x\n)); Spread is shallow. [...prev] followed by changing a nested object still mutates shared data."}, {"title": "Event function versus call", "url": "cheatsheet.html#cheat-5", "category": "Syntax reference", "terms": "Event function versus call Pass a function to an event prop. Use a wrapper when choosing arguments. <Button title=\"Save\" onPress={save} />\n<Pressable onPress={() => removeItem(item.id)} /> onPress={save()} invokes save during render. It usually passes the wrong value and may cause repeated updates."}, {"title": "Callback props", "url": "cheatsheet.html#cheat-6", "category": "Syntax reference", "terms": "Callback props The parent owns shared state and sends a callback contract to the child. This callback accepts a draft; the parent supplies a stable ID when it creates the stored item. type Draft = { name: string; popular: boolean };\ntype Props = { onAdd: (draft: Draft) => void };\n// Parent JSX: <Composer onAdd={addItem} />\n// Child event: onAdd({ name, popular }); The child must construct the argument shape the callback expects. Props travel down; the callback reports an action to the owner."}, {"title": "Controlled text input", "url": "cheatsheet.html#cheat-7", "category": "Syntax reference", "terms": "Controlled text input The displayed value and change callback must refer to the same state. <TextInput value={name} onChangeText={setName} />\nconst cleanName = name.trim();\n// In submit handler: if (!cleanName) return; onChangeText gives a string, not a browser event. A fixed value without an update makes edits appear stuck."}, {"title": "JSX and conditions", "url": "cheatsheet.html#cheat-8", "category": "Syntax reference", "terms": "JSX and conditions Use expressions inside JSX braces and put visible strings in Text. {count > 0 ? <Text>{count} items<\/Text> : null}\n<Text style={{ fontSize: 18 }}>Hello<\/Text> 0 && <Text>...<\/Text> evaluates to 0. Double braces in style={{...}} are a JSX expression containing an object."}, {"title": "Flexbox axes", "url": "cheatsheet.html#cheat-9", "category": "Syntax reference", "terms": "Flexbox axes The parent controls direct children. React Native defaults to column. row: {\n  flexDirection: 'row',\n  justifyContent: 'space-between',\n  alignItems: 'center',\n} justifyContent uses the main axis; alignItems uses the cross axis. With column, the main axis is vertical."}, {"title": "Box model and dimensions", "url": "cheatsheet.html#cheat-10", "category": "Syntax reference", "terms": "Box model and dimensions Padding is inside the border; margin is outside. Numeric sizes are logical layout units. card: {\n  margin: 16, padding: 16,\n  borderWidth: 1, borderColor: '#667085',\n  borderRadius: 12,\n} Use camelCase style names. A percentage or flex size needs a parent with usable dimensions; avoid assuming flex: 1 means full screen in every context."}, {"title": "Import and export pairs", "url": "cheatsheet.html#cheat-11", "category": "Syntax reference", "terms": "Import and export pairs A module has at most one default export and can have several named exports. // Card.tsx: export default Card; export const color = 'navy';\nimport Card, { color } from './Card';\nimport type { Item } from './types'; Default imports do not use braces. Named imports match the export or use an explicit as alias."}, {"title": "Effect and cleanup", "url": "cheatsheet.html#cheat-12", "category": "Syntax reference", "terms": "Effect and cleanup Use an effect to synchronize with an external system and clean up resources. useEffect(() => {\n  if (!running) return;\n  const id = setInterval(() => setSeconds(s => s + 1), 1000);\n  return () => clearInterval(id);\n}, [running]); Do not call hooks conditionally. [] is mount-oriented, but development Strict Mode may run an extra setup-cleanup cycle."}, {"title": "Promise values and order", "url": "cheatsheet.html#cheat-13", "category": "Syntax reference", "terms": "Promise values and order then attaches a reaction and returns a Promise. Return a value to pass it onward. console.log('A');\nPromise.resolve(3)\n  .then(n => n * 2)\n  .then(n => console.log(n));\nconsole.log('B'); // A, B, then 6 A missing return in a block causes the next stage to receive undefined. Promise callbacks run after current synchronous work."}, {"title": "Debug in a useful order", "url": "cheatsheet.html#cheat-14", "category": "Syntax reference", "terms": "Debug in a useful order Read the exact error, identify the smallest failing expression, and predict a test before editing. // Ask: What value is expected here?\n// Is this an array [], object {}, function (), or JSX element?\n// Is this callback being passed, called, or returning a value? Do not fix several unrelated things at once. A small compiling fragment is easier to extend than a large unfinished component."}];
